    [986] = {name = "Tome of Frostbolt II", additional_info = "Classes: Mage\nRequires Level 8\n[q2]Use: Teaches Frostbolt (Rank 2).\n[q2]Launches a bolt of frost at the enemy, causing [31 * ( ( ( ( 1 ) ) ) * ( 1 ) )] to [35 * ( ( ( ( 1 ) ) ) * ( 1 ) )] Frost damage and slowing movement speed by 40% for 6 sec.\nSell Price: 50"},
    [989] = {name = "Tome of Frost Nova", additional_info = "Classes: Mage\nRequires Level 10\n[q2]Use: Teaches Frost Nova (Rank 1).\n[q2]Blasts enemies near the caster for [19 * ( ( ( ( 1 ) ) ) * ( 1 ) )] to [21 * ( ( ( ( 1 ) ) ) * ( 1 ) )] Frost damage and freezes them in place for up to 8 sec. Damage caused may interrupt the effect.\nSell Price: 75"},
    [992] = {name = "Tome of Fireball III", additional_info = "Classes: Mage\nRequires Level 12\n[q2]Use: Teaches Fireball (Rank 3).\n[q2]Hurls a fiery ball that causes 57 to 77 Fire damage and an additional 6 Fire damage over 6 sec.\nSell Price: 1 25"},
