    [1029] = {name = "Tablet of Serpent Totem", additional_info = "Classes: Shaman\nRequires Level 4\n[q2]Use: Teaches Serpent Totem (Rank 1).\n[q2]Summons a Searing Totem with 5 health at your feet for 30 sec that repeatedly attacks an enemy within 20 yards for 9 to 11 Fire damage.\nSell Price: 20"},
