    [1032] = {name = "Tablet of Agitating Totem", additional_info = "Classes: Shaman\nRequires Level 8\n[q2]Use: Teaches Agitating Totem (Rank 1).\n[q2]Summons a Stoneclaw Totem with [50 + floor(Stamina * 0.05)]\n health at the feet of the caster for 15 sec that taunts creatures within 8 yards to attack it. Enemies attacking the Stoneclaw Totem have a 50% chance to be stunned for 3 sec. Stoneclaw totem also protects all your totems, causing them to absorb 21 damage.\nSell Price: 87"},
    [1033] = {name = "Tablet of Nullify Poison", additional_info = "Classes: Shaman\nRequires Level 18\n[q2]Use: Teaches Cure Poison (Rank 1).\n[q2]Cures 1 poison effect and 1 disease effect on a friendly target.\nSell Price: 6 25"},
