    [1048] = {name = "Tablet of Lightning Shield II", additional_info = "Classes: Shaman\nRequires Level 16\n[q2]Use: Teaches Lightning Shield (Rank 2).\n[q2]The caster is surrounded by 3 balls of lightning. When a spell, melee or ranged attack hits the caster, the attacker will be struck for 29 Nature damage. This expends one lightning ball. Only one ball will fire every few seconds. Lasts 10 min. Only one Elemental Shield can be active on the Shaman at any one time. (3.5s cooldown)\nSell Price: 3 25"},
    [1049] = {name = "Tablet of Purge", additional_info = "Classes: Shaman\nRequires Level 12\n[q2]Use: Teaches Purge.\n[q2]Purges the enemy target, removing 1 beneficial magic effect.\nSell Price: 1 50"},
