    [4141] = {name = "Tome of Conjure Food", additional_info = "Classes: Mage\nRequires Level 6\n[q2]Use: Teaches Conjure Food (Rank 1).\n[q2]Conjures 20 muffins, providing the mage and his allies with something to eat.\n\n Conjured items disappear if logged out for more than 15 minutes.\nSell Price: 20\nConjured Muffin\nConjured Item\n[q2]Use: Restores 61.2 health over 18 sec. Must remain seated while eating."},
    [4143] = {name = "Tome of Conjure Food II", additional_info = "Classes: Mage\nRequires Level 12\n[q2]Use: Teaches Conjure Food (Rank 2).\n[q2]Conjures 20 loaves of bread, providing the mage and his allies with something to eat.\n\n Conjured items disappear if logged out for more than 15 minutes.\nSell Price: 1 25\nConjured Bread\nConjured Item\nRequires Level 5\n[q2]Use: Restores 243.6 health over 21 sec. Must remain seated while eating."},
    [4145] = {name = "Tome of Conjure Mana Gem", additional_info = "Classes: Mage\nRequires Level 28\n[q2]Use: Teaches Conjure Mana Gem.\n[q2]Conjures a mana agate that can be used to instantly restore 390 to 410 mana.\nSell Price: 20 25\nMana Agate\nBinds when picked up\nUnique: Mana Gem (1)\nRequires Level 28\n[q2]Use: Restores 390 to 410 mana. (2 Min Cooldown)"},
    [4146] = {name = "Tome of Polymorph: Sheep", additional_info = "Classes: Mage\nRequires Level 40\n[q2]Use: Teaches Polymorph: Sheep.\n[q2]Transforms the enemy into a helpless sheep that cannot cast spells or attack and movement speed is reduced by 60% for up to 10 sec.\nSell Price: 50"},
    [4147] = {name = "Tome of Conjure Food III", additional_info = "Classes: Mage\nRequires Level 22\n[q2]Use: Teaches Conjure Food (Rank 3).\n[q2]Conjures 20 loaves of rye, providing the mage and his allies with something to eat.\n\n Conjured items disappear if logged out for more than 15 minutes.\nSell Price: 10 50\nConjured Rye\nConjured Item\nRequires Level 15\n[q2]Use: Restores 552 health over 24 sec. Must remain seated while eating."},
    [4148] = {name = "Tome of Counterspell", additional_info = "Classes: Mage\nRequires Level 24\n[q2]Use: Teaches Counterspell.\n[q2]Counters the enemy's spellcast, preventing any spell from that school of magic from being cast for 8 sec. Generates a high amount of threat.\nSell Price: 13 25"},
    [4149] = {name = "Tome of Frost Shield III", additional_info = "Classes: Mage\nRequires Level 34\n[q2]Use: Teaches Frost Shield (Rank 3).\nSell Price: 30"},
    [4150] = {name = "Tome of Conjure Water IV", additional_info = "Classes: Mage\nRequires Level 30\n[q2]Use: Teaches Conjure Water (Rank 4).\n[q2]Conjures 20 bottles of spring water, providing the mage and his allies with something to drink.\n\n Conjured items disappear if logged out for more than 15 minutes.\nSell Price: 24 25\nConjured Spring Water\nConjured Item\nRequires Level 25\n[q2]Use: Restores 1345 mana over 27 sec. Must remain seated while drinking."},
    [4151] = {name = "Tome of Frostbolt IV", additional_info = "Classes: Mage\nRequires Level 20\n[q2]Use: Teaches Frostbolt (Rank 4).\n[q2]Launches a bolt of frost at the enemy, causing [74 * ( ( ( ( 1 ) ) ) * ( 1 ) )] to [82 * ( ( ( ( 1 ) ) ) * ( 1 ) )] Frost damage and slowing movement speed by 40% for 7 sec.\nSell Price: 7 25"},
    [4152] = {name = "Tome of Conjure Food IV", additional_info = "Classes: Mage\nRequires Level 32\n[q2]Use: Teaches Conjure Food (Rank 4).\n[q2]Conjures 20 loaves of pumpernickel, providing the mage and his allies with something to eat.\n\n Conjured items disappear if logged out for more than 15 minutes.\nSell Price: 27 50\nConjured Pumpernickel\nConjured Item\nRequires Level 25\n[q2]Use: Restores 874.8 health over 27 sec. Must remain seated while eating."},
    [4153] = {name = "Tome of Arcane Missiles III", additional_info = "Classes: Mage\nRequires Level 24\n[q2]Use: Teaches Arcane Missiles (Rank 3).\n[q2]Launches Arcane Missiles at the enemy, causing 58 Arcane damage every 1 sec for 5 sec.\nSell Price: 13 25"},
    [4154] = {name = "Tome of Slow II", additional_info = "Classes: Mage\nRequires Level 40\n[q2]Use: Teaches Slow (Rank 2).\n[q2]Slows the enemy's movement by 60% and their attack speed by 54% for 15 sec.\nSell Price: 50"},
    [4155] = {name = "Tome of Water Elemental II", additional_info = "Classes: Mage\nRequires Level 40\n[q2]Use: Teaches Water Elemental (Rank 2).\nSell Price: 50"},
    [4157] = {name = "Tome of Dampen Magic", additional_info = "Classes: Mage\nRequires Level 12\n[q2]Use: Teaches Dampen Magic (Rank 1).\n[q2]Dampens magic used against the targeted party member, decreasing damage taken from spells by up to 10 and healing spells by up to 11. Lasts 10 min.\nSell Price: 1 25"},
    [4158] = {name = "Tome of Khadgar's Unlocking III", additional_info = "Classes: Mage\nRequires Level 42\n[q2]Use: Teaches Agitating Totem (Rank 4).\n[q2]Summons a Stoneclaw Totem with [280 + floor(Stamina * 0.05)]\n health at the feet of the caster for 15 sec that taunts creatures within 8 yards to attack it. Enemies attacking the Stoneclaw Totem have a 50% chance to be stunned for 3 sec. Stoneclaw totem also protects all your totems, causing them to absorb 170 damage.\nSell Price: 55"},
    [4159] = {name = "Tome of Arcane Missiles", additional_info = "Classes: Mage\nRequires Level 8\n[q2]Use: Teaches Arcane Missiles (Rank 1).\n[q2]Launches Arcane Missiles at the enemy, causing 26 Arcane damage every 1 sec for 3 sec.\nSell Price: 50"},
    [4161] = {name = "Tome of Fireball IV", additional_info = "Classes: Mage\nRequires Level 18\n[q2]Use: Teaches Fireball (Rank 4).\n[q2]Hurls a fiery ball that causes 89 to 122 Fire damage and an additional 12 Fire damage over 8 sec.\nSell Price: 5 50"},
    [4162] = {name = "Tome of Blink II", additional_info = "Classes: Mage\nRequires Level 38\n[q2]Use: Teaches Blink (Rank 2).\n[q2]Teleports the caster 20 yards forward, unless something is in the way. Also frees the caster from any bonds.\nSell Price: 42 50"},
    [4164] = {name = "Libram: Holy Light V", additional_info = "Classes: Paladin\nRequires Level 30\n[q2]Use: Teaches Holy Light (Rank 5).\n[q2]Heals a friendly target for 643 to 724.\nSell Price: 24 25"},
    [4165] = {name = "Libram: Holy Light VI", additional_info = "Classes: Paladin\nRequires Level 38\n[q2]Use: Teaches Holy Light (Rank 6).\n[q2]Heals a friendly target for 913 to 1017.\nSell Price: 45"},
    [4166] = {name = "Libram: Seal of Protection", additional_info = "Classes: Paladin\nRequires Level 8\n[q2]Use: Teaches Seal of Protection (Rank 1).\n[q2]A targeted party or raid member is protected from all physical attacks for 6 sec, but during that time they cannot attack or use physical abilities. Players may only have one Hand on them per Paladin at any one time. Once protected, the target cannot be targeted by Divine Shield, Divine Protection, or Hand of Protection again for 2 min. Cannot be targeted on players who have used Avenging Wrath within the last 30 sec.\nSell Price: 50"},
    [4167] = {name = "Libram: Judgement", additional_info = "Classes: Paladin\nRequires Level 40\n[q2]Use: Teaches Judgement.\n[q2]Sends bolts of holy power in all directions, causing (399 + 0.07 * Spell power + 0.07 * Attack power) to (471 + 0.07 * Spell power + 0.07 * Attack power) Holy damage and stunning all Undead and Demon targets within 10 yds for 3 sec.\nSell Price: 50"},
    [4168] = {name = "Tablet of Ensnaring Totem", additional_info = "Classes: Shaman\nRequires Level 16\n[q2]Use: Teaches Earthbind Totem.\n[q2]Summons an Earthbind Totem with 5 health at the feet of the caster for 45 sec that slows the movement speed of enemies within 10 yards.\nSell Price: 4 50"},
    [4169] = {name = "Tablet of Unyielding Will II", additional_info = "Classes: Shaman\nRequires Level 24\n[q2]Use: Teaches Unyielding Will (Rank 2).\nSell Price: 12 50"},
    [4170] = {name = "Tablet of Astral Recall", additional_info = "Classes: Shaman\nRequires Level 30\n[q2]Use: Teaches Astral Recall.\n[q2]Yanks the caster through the twisting nether back to <Hearthstone Location>. Speak to an Innkeeper in a different place to change your home location.\nSell Price: 20"},
    [4171] = {name = "Tablet of Agitating Totem III", additional_info = "Classes: Shaman\nRequires Level 28\n[q2]Use: Teaches Agitating Totem (Rank 3).\n[q2]Summons a Stoneclaw Totem with [220 + floor(Stamina * 0.05)] health at the feet of the caster for 15 sec that taunts creatures within 8 yards to attack it. Enemies attacking the Stoneclaw Totem have a 50% chance to be stunned for 3 sec. Stoneclaw totem also protects all your totems, causing them to absorb 108 damage.\nSell Price: 17 50"},
    [4172] = {name = "Tablet of Thunderclap II", additional_info = "Classes: Shaman\nRequires Level 36\n[q2]Use: Teaches Thunderclap (Rank 2).\nSell Price: 37 50"},
    [4173] = {name = "Tablet of Shock IV", additional_info = "Classes: Shaman\nRequires Level 28\n[q2]Use: Teaches Shock (Rank 4).\n[q2]Instantly throws a bolt of lightning at the target for 191 to 202 damage.\nSell Price: 17 50"},
    [4174] = {name = "Tablet of Shock V", additional_info = "Classes: Shaman\nRequires Level 36\n[q2]Use: Teaches Shock (Rank 5).\n[q2]Instantly throws a bolt of lightning at the target for 269 to 286 damage.\nSell Price: 37 50"},
    [4175] = {name = "Tablet of Lightning Shield IV", additional_info = "Classes: Shaman\nRequires Level 32\n[q2]Use: Teaches Lightning Shield (Rank 4).\n[q2]The caster is surrounded by 3 balls of lightning. When a spell, melee or ranged attack hits the caster, the attacker will be struck for 80 Nature damage. This expends one lightning ball. Only one ball will fire every few seconds. Lasts 10 min. Only one Elemental Shield can be active on the Shaman at any one time. (3.5s cooldown)\nSell Price: 27 50"},
