    [4406] = {name = "Standard Scope", additional_info = "Requires Level 10\n[q2]Use: Attaches a permanent scope to a bow or gun that increases its damage by 2.\nSell Price: 6"},
    [4407] = {name = "[q2]Accurate Scope", additional_info = "Requires Level 20\n[q2]Use: Attaches a permanent scope to a bow or gun that increases its damage by 3.\n\n Attaching this scope to a ranged weapon causes it to become soulbound.\nSell Price: 12"},
    [4408] = {name = "[q2]Schematic: Mechanical Squirrel Box", additional_info = "Requires Engineering (75)\n[q2]Use: Teaches you how to make a Mechanical Squirrel Box.\nSell Price: 1 62\nMechanical Squirrel Box\n[q2]Use: Teaches you how to summon this companion.\n[q2]Creates a Mechanical Squirrel that follows you around. Right Click to summon and dismiss your Squirrel.\nSell Price: 1\nRequires Copper Modulator , Handful of Copper Bolts , Copper Bar , Malachite (2)"},
    [4409] = {name = "[q2]Schematic: Small Seaforium Charge", additional_info = "Requires Engineering (100)\n[q2]Use: Teaches you how to make a Small Seaforium Charge.\n[q2]A Small Seaforium charge which is enough to blast open some doors.\nSell Price: 2\nSmall Seaforium Charge\nRequires Engineering (100)\n[q2]Use: Blasts open simple locked doors and chests.\nSell Price: 1 50\nRequires Coarse Blasting Powder (2), Copper Modulator , Light Leather , Refreshing Spring Water"},
    [4410] = {name = "[q2]Schematic: Shadow Goggles", additional_info = "Requires Engineering (120)\n[q2]Use: Teaches you how to make Shadow Goggles.\nSell Price: 2 50\n[q2]Shadow Goggles\nBinds when equipped\nHead Cloth\n31 Armor\n+5 Intellect\n+6 Spirit\nDurability 40 / 40\nRequires Engineering (120)\nSell Price: 7 22\nRequires Medium Leather (4), Shadowgem (2)"},
    [4411] = {name = "[q2]Schematic: Flame Deflector", additional_info = "Requires Engineering (125)\n[q2]Use: Teaches you how to make a Flame Deflector.\nSell Price: 2 75\nFlame Deflector\nRequires Level 15\n[q2]Use: Absorbs 500 fire damage. Lasts 1 min. (15 Min Cooldown)\n5 ChargesSell Price: 2\nRequires Whirring Bronze Gizmo , Small Flame Sac"},
    [4412] = {name = "[q2]Schematic: Moonsight Rifle", additional_info = "Requires Engineering (145)\n[q2]Use: Teaches you how to make a Moonsight Rifle.\nSell Price: 3 75\n[q2]Moonsight Rifle\nBinds when equipped\nRanged Gun\n19 - 35 Damage Speed 1.70\n(15.88 damage per second)\nDurability 65 / 65\nRequires Level 24\nSell Price: 31 83\nRequires Bronze Tube (3), Whirring Bronze Gizmo (3), Heavy Stock , Lesser Moonstone (2)"},
    [4413] = {name = "[q2]Schematic: Discombobulator Ray", additional_info = "Requires Engineering (160)\n[q2]Use: Teaches you how to make a Discombobulator Ray.\nSell Price: 4 50\nDiscombobulator Ray\n[q2]Use: Transforms the target into a Leper Gnome, reducing its melee damage and spell power by 40 and its movement rate by 20% for 12 sec. (1 Min Cooldown)\n5 ChargesSell Price: 10\nRequires Whirring Bronze Gizmo (3), Silk Cloth (2), Jade , Bronze Tube"},
    [4414] = {name = "[q2]Schematic: Portable Bronze Mortar", additional_info = "Requires Engineering (165)\n[q2]Use: Teaches you how to make a Portable Bronze Mortar.\nSell Price: 4 62\nPortable Bronze Mortar\nRequires Engineering (165)\n[q2]Use: Inflicts 85 to 115 Fire damage and incapacitates targets in a 5 yard radius for 2 sec. Any damage will break the effect. Unreliable against targets higher than level 44. (1 Min Cooldown)\n8 ChargesSell Price: 20\nRequires Bronze Tube (4), Iron Strut , Heavy Blasting Powder (4), Medium Leather (4)"},
    [4415] = {name = "[q3]Schematic: Craftsman's Monocle", additional_info = "Requires Engineering (185)\n[q2]Use: Teaches you how to make a Craftman's Monocle.\nSell Price: 5 50\n[q2]Craftsman's Monocle\nBinds when equipped\nHead Cloth\n40 Armor\n+15 Intellect\nDurability 45 / 45\nRequires Engineering (185)\nSell Price: 26 32\nRequires Heavy Leather (6), Citrine (2)"},
    [4416] = {name = "[q2]Schematic: Goblin Land Mine", additional_info = "Requires Engineering (195)\n[q2]Use: Teaches you how to make a Goblin Land Mine.\n[q2]Build a Goblin Land Mine.\nSell Price: 6\nGoblin Land Mine\nRequires Engineering (195)\n[q2]Use: Places the Goblin Land Mine on the ground. It will explode for 394 to 506 fire damage the next time a hostile creature passes near it. The mine has a duration of 1 min. (1 Min Cooldown)\nSell Price: 16\nRequires Heavy Blasting Powder (3), Iron Bar (2), Gyrochronatom"},
    [4417] = {name = "[q2]Schematic: Large Seaforium Charge", additional_info = "Requires Engineering (200)\n[q2]Use: Teaches you how to make a Large Seaforium Charge.\nSell Price: 6 75\nLarge Seaforium Charge\nRequires Engineering (200)\n[q2]Use: Blasts open difficult locked doors and chests.\nSell Price: 9\nRequires Solid Blasting Powder (2), Heavy Leather (2), Refreshing Spring Water"},
