    [5643] = {name = "Recipe: Great Rage Potion", additional_info = "Requires Alchemy (175)\n[q2]Use: Teaches you how to make a Great Rage Potion.\nSell Price: 5\nGreat Rage Potion\nClasses: Warrior , Druid\nRequires Level 25\n[q2]Use: Increases Rage by 30 to 60. (1 Min Cooldown)\nSell Price: 1 50\nRequires Large Fang , Kingsblood , Leaded Vial"},
    [5644] = {name = "Tome of Conjure Water", additional_info = "Classes: Mage\nRequires Level 4\n[q2]Use: Teaches Conjure Water (Rank 1).\n[q2]Conjures 20 bottles of water, providing the mage and his allies with something to drink.\n\n Conjured items disappear if logged out for more than 15 minutes.\nSell Price: 10\nConjured Water\nConjured Item\n[q2]Use: Restores 151 mana over 18 sec. Must remain seated while drinking."},
