    [5646] = {name = "Vial of Blessed Water", additional_info = "Quest Item\nUnique"},
    [5647] = {name = "Tome of Blink", additional_info = "Classes: Mage\nRequires Level 22\n[q2]Use: Teaches Blink (Rank 1).\n[q2]Teleports the caster 20 yards forward, unless something is in the way. Also frees the caster from stuns and bonds.\nSell Price: 10"},
    [5648] = {name = "Tome of Frost Armor III", additional_info = "Classes: Mage\nRequires Level 20\n[q2]Use: Teaches Frost Armor (Rank 3).\n[q2]Increases Armor by 200. If an enemy strikes the caster, they may have their movement slowed by 30% and the time between their attacks increased by 25% for 5 sec. Only one type of Armor spell can be active on the Mage at any time. Lasts 30 min.\nSell Price: 7 25"},
    [5649] = {name = "Tome of Blizzard", additional_info = "Classes: Mage\nRequires Level 20\n[q2]Use: Teaches Blizzard (Rank 1).\n[q2]Ice shards pelt the target area doing [ 37 * 8 * ( ( ( ( 1 ) ) ) * ( 1 ) )] Frost damage over 8 sec.\nSell Price: 7 25"},
    [5650] = {name = "Tome of Conjure Water III", additional_info = "Classes: Mage\nRequires Level 20\n[q2]Use: Teaches Conjure Water (Rank 3).\n[q2]Conjures 20 bottles of purified water, providing the mage and his allies with something to drink.\n\n Conjured items disappear if logged out for more than 15 minutes.\nSell Price: 7 25\nConjured Purified Water\nConjured Item\nRequires Level 15\n[q2]Use: Restores 835 mana over 24 sec. Must remain seated while drinking."},
    [5654] = {name = "Instant Toxin", additional_info = "Classes: Rogue\nRequires Level 24\n[q2]Use: Coats a sword or dagger with poison that lasts for 30 minutes.\n Each strike has a chance of poisoning the enemy which instantly inflicts 10-30 damage.\nSell Price: 1"},
