    [5672] = {name = "Libram: Exorcism", additional_info = "Classes: Paladin\nRequires Level 20\n[q2]Use: Teaches Exorcism (Rank 1).\n[q2]Causes (96 + 0.15 * Spell power + 0.15 * Attack power) to (110 + 0.15 * Spell power + 0.15 * Attack power) Holy damage to an enemy target. If the target is Undead or Demon, it will always critically hit.\nSell Price: 7 25"},
    [5673] = {name = "Libram: Exorcism II", additional_info = "Classes: Paladin\nRequires Level 28\n[q2]Use: Teaches Exorcism (Rank 2).\n[q2]Causes (173 + 0.15 * Spell power + 0.15 * Attack power) to (195 + 0.15 * Spell power + 0.15 * Attack power) Holy damage to an enemy target. If the target is Undead or Demon, it will always critically hit.\nSell Price: 20 25"},
    [5674] = {name = "Libram: Exorcism III", additional_info = "Classes: Paladin\nRequires Level 36\n[q2]Use: Teaches Exorcism (Rank 3).\n[q2]Causes (250 + 0.15 * Spell power + 0.15 * Attack power) to (282 + 0.15 * Spell power + 0.15 * Attack power) Holy damage to an enemy target. If the target is Undead or Demon, it will always critically hit.\nSell Price: 37 50"},
    [5675] = {name = "Crystalized Scales", additional_info = "Quest Item"},
    [5676] = {name = "Libram: Sense Undead", additional_info = "Classes: Paladin\nRequires Level 20\n[q2]Use: Teaches Sense Undead.\n[q2]Shows the location of all nearby undead on the minimap until cancelled.  Only one form of tracking can be active at a time.\nSell Price: 7 25"},
    [5677] = {name = "Libram: Turn Undead", additional_info = "Classes: Paladin\nRequires Level 24\n[q2]Use: Teaches Turn Undead (Rank 1).\nSell Price: 13 25"},
    [5679] = {name = "Libram: Seal of Wisdom III", additional_info = "Classes: Paladin\nRequires Level 36\n[q2]Use: Teaches Seal of Wisdom (Rank 3).\nSell Price: 37 50"},
    [5680] = {name = "Libram: Seal of Protection II", additional_info = "Classes: Paladin\nRequires Level 20\n[q2]Use: Teaches Seal of Protection (Rank 2).\n[q2]A targeted party or raid member is protected from all physical attacks for 8 sec, but during that time they cannot attack or use physical abilities. Players may only have one Hand on them per Paladin at any one time. Once protected, the target cannot be targeted by Divine Shield, Divine Protection, or Hand of Protection again for 2 min. Cannot be targeted on players who have used Avenging Wrath within the last 30 sec.\nSell Price: 7 25"},
    [5681] = {name = "Corrosive Sap", additional_info = "Quest Item"},
    [5682] = {name = "Libram: Turn Undead II", additional_info = "Classes: Paladin\nRequires Level 38\n[q2]Use: Teaches Turn Undead (Rank 2).\nSell Price: 45"},
    [5683] = {name = "Libram: Divine Shield II", additional_info = "Classes: Paladin\nRequires Level 50\n[q2]Use: Teaches Divine Shield (Rank 2).\nSell Price: 87 50"},
    [5684] = {name = "Libram: Seal of Salvation", additional_info = "Classes: Paladin\nRequires Level 22\n[q2]Use: Teaches Seal of Salvation (Rank 1).\n[q2]Places a Hand on the party or raid member, reducing their total threat by 2% every 1 sec. for 10 sec. Players may only have one Hand on them per Paladin at any one time.\nSell Price: 10 50"},
    [5685] = {name = "Libram: Redemption", additional_info = "Classes: Paladin\nRequires Level 40\n[q2]Use: Teaches Redemption.\nSell Price: 50"},
