    [5696] = {name = "Tablet of Shock", additional_info = "Classes: Shaman\nRequires Level 4\n[q2]Use: Teaches Shock (Rank 1).\n[q2]Instantly throws a bolt of lightning at the target for 25 to 28 damage.\nSell Price: 20"},
    [5697] = {name = "Tablet of Healing Totem", additional_info = "Classes: Shaman\nRequires Level 6\n[q2]Use: Teaches Healing Totem (Rank 1).\n[q2]Summons a Healing Stream Totem with 5 health at the feet of the caster for 5 min that heals group members within 30 yards for 6 every 2 seconds.\nSell Price: 50"},
    [5698] = {name = "Tablet of Lightning Shield", additional_info = "Classes: Shaman\nRequires Level 8\n[q2]Use: Teaches Lightning Shield (Rank 1).\n[q2]The caster is surrounded by 3 balls of lightning. When a spell, melee or ranged attack hits the caster, the attacker will be struck for 13 Nature damage. This expends one lightning ball. Only one ball will fire every few seconds. Lasts 10 min. Only one Elemental Shield can be active on the Shaman at any one time. (3.5s cooldown)\nSell Price: 50"},
    [5699] = {name = "Tablet of Ghost Wolf", additional_info = "Classes: Shaman\nRequires Level 12\n[q2]Use: Teaches Ghost Wolf (Rank 1).\n[q2]Turns the Shaman into a Ghost Wolf, increasing speed by 40%\n\nGlyph of Ghost Wolf\nand regenerating 1% of your maximum health every 5 sec\n\n As a Ghost Wolf, the Shaman is less hindered by effects that would reduce movement speed. Only useable outdoors.\nSell Price: 2 50"},
    [5700] = {name = "Tablet of Healing Totem II", additional_info = "Classes: Shaman\nRequires Level 12\n[q2]Use: Teaches Healing Totem (Rank 2).\n[q2]Summons a Healing Stream Totem with 5 health at the feet of the caster for 5 min that heals group members within 30 yards for 8 every 2 seconds.\nSell Price: 2 50"},
    [5701] = {name = "Tablet of Sentry Totem", additional_info = "Classes: Shaman\nRequires Level 14\n[q2]Use: Teaches Sentry Totem.\n[q2]Summons an immobile Sentry Totem with 100 health at your feet for 5 min that allows vision of nearby area and warns of enemies that attack it. Right-Click on buff to switch back and forth between totem sight and shaman sight.\nSell Price: 3 25"},
    [5702] = {name = "Tablet of Agitating Totem II", additional_info = "Classes: Shaman\nRequires Level 18\n[q2]Use: Teaches Agitating Totem (Rank 2).\n[q2]Summons a Stoneclaw Totem with [150 + floor(Stamina * 0.05)] health at the feet of the caster for 15 sec that taunts creatures within 8 yards to attack it. Enemies attacking the Stoneclaw Totem have a 50% chance to be stunned for 3 sec. Stoneclaw totem also protects all your totems, causing them to absorb 58 damage.\nSell Price: 6 25"},
    [5703] = {name = "Tablet of Thunderclap", additional_info = "Classes: Shaman\nRequires Level 20\n[q2]Use: Teaches Thunder Clap (Rank 1).\n[q2]Blasts nearby enemies increasing the time between their attacks by 10% for 10 sec and doing 15 damage to them. Damage increased by attack power. This ability causes additional threat.\nSell Price: 7 50"},
    [5704] = {name = "Tablet of Water Breathing", additional_info = "Classes: Shaman\nRequires Level 20\n[q2]Use: Teaches Water Breathing.\n[q2]Allows the target to breathe underwater for 10 min.\nSell Price: 7 50"},
    [5705] = {name = "Tablet of Healing Totem III", additional_info = "Classes: Shaman\nRequires Level 20\n[q2]Use: Teaches Healing Totem (Rank 3).\n[q2]Summons a Healing Stream Totem with 5 health at the feet of the caster for 5 min that heals group members within 30 yards for 10 every 2 seconds.\nSell Price: 7 50"},
    [5706] = {name = "Tablet of Serpent Totem III", additional_info = "Classes: Shaman\nRequires Level 20\n[q2]Use: Teaches Serpent Totem (Rank 3).\n[q2]Summons a Searing Totem with 5 health at your feet for 40 sec that repeatedly attacks an enemy within 20 yards for 19 to 25 Fire damage.\nSell Price: 7 50"},
    [5707] = {name = "Tablet of Far Sight", additional_info = "Classes: Shaman\nRequires Level 26\n[q2]Use: Teaches Far Sight.\n[q2]Changes the caster's viewpoint to the targeted location. Lasts 1 min. Only useable outdoors.\nSell Price: 16 75"},
    [5708] = {name = "Tablet of Ethereal Form", additional_info = "Classes: Shaman\nRequires Level 24\n[q2]Use: Teaches Ethereal Form (Rank 1).\nSell Price: 12 50"},
    [5709] = {name = "Tablet of Water Walking", additional_info = "Classes: Shaman\nRequires Level 28\n[q2]Use: Teaches Water Walking.\n[q2]Allows the friendly target to walk across water for 10 min. Any damage will cancel the effect.\nSell Price: 17 50"},
    [5710] = {name = "Tablet of Healing Totem IV", additional_info = "Classes: Shaman\nRequires Level 28\n[q2]Use: Teaches Healing Totem (Rank 4).\nSell Price: 17 50"},
    [5711] = {name = "Tablet of Ghost Wolf II", additional_info = "Classes: Shaman\nRequires Level 30\n[q2]Use: Teaches Ghost Wolf (Rank 2).\nSell Price: 20"},
    [5712] = {name = "Tablet of Serpent Totem IV", additional_info = "Classes: Shaman\nRequires Level 30\n[q2]Use: Teaches Serpent Totem (Rank 4).\n[q2]Summons a Searing Totem with 5 health at your feet for 45 sec that repeatedly attacks an enemy within 20 yards for 26 to 34 Fire damage.\nSell Price: 20"},
    [5713] = {name = "Tablet of Thunderbolt", additional_info = "Classes: Shaman\nRequires Level 32\n[q2]Use: Teaches Thunderbolt.\n[q2]Wards the friendly target against Fear. The next Fear effect used against the target will fail, using up the ward. Lasts 3 min.\nSell Price: 25"},
