    [5719] = {name = "Grimoire of Life Drain II", additional_info = "Classes: Warlock\nRequires Level 22\n[q2]Use: Teaches Drain Life (Rank 2).\n[q2]Transfers 17 health every 1 sec from the target to the caster. Lasts 5 sec.\nSell Price: 10 50"},
    [5720] = {name = "Grimoire of Curse of Mannoroth II", additional_info = "Classes: Warlock\nRequires Level 20\n[q2]Use: Teaches Curse of Weakness (Rank 2).\n[q2]Target's melee attack power is reduced by 41 and armor is reduced by 5% for 2 min. Only one Curse per Warlock can be active on any one target.\nSell Price: 7 50"},
    [5721] = {name = "Grimoire of Create Spellstone", additional_info = "Classes: Warlock\nRequires Level 34\n[q2]Use: Teaches Create Spellstone.\n[q2]While applied to target weapon it increases damage dealt by periodic spells by 1% and spell haste rating by 10. Lasts for 1 hour.\nSell Price: 30\nSpellstone\nBinds when picked up\nUnique\n[q2]Use: While applied to target weapon it increases damage dealt by periodic spells by 1% and spell haste rating by 10. Lasts for 1 hour.\n5 ChargesRequires Soul Shard"},
    [5722] = {name = "Grimoire of Siphon Mana II", additional_info = "Classes: Warlock\nRequires Level 36\n[q2]Use: Teaches Drain Mana (Rank 2).\nSell Price: 45"},
    [5723] = {name = "Grimoire of Curse of Sargeras III", additional_info = "Classes: Warlock\nRequires Level 36\n[q2]Use: Teaches Curse of Agony (Rank 3).\n[q2]Curses the target with agony, causing 324 Shadow damage over 24 sec. This damage is dealt slowly at first, and builds up as the Curse reaches its full duration. Only one Curse per Warlock can be active on any one target.\nSell Price: 37 50"},
    [5724] = {name = "Grimoire of Curse of Tongues", additional_info = "Classes: Warlock\nRequires Level 22\n[q2]Use: Teaches Curse of Tongues (Rank 1).\n[q2]Forces the target to speak in Demonic, increasing the casting time of all spells by 25%. Only one Curse per Warlock can be active on any one target. Lasts 30 sec.\nSell Price: 10 50"},
    [5725] = {name = "Grimoire of Pestilence III", additional_info = "Classes: Warlock\nRequires Level 38\n[q2]Use: Teaches Corruption (Rank 3).\n[q2]Corrupts the target, causing 222 Shadow damage over 18 sec.\nSell Price: 42 50"},
