    [9189] = {name = "Shay's Bell", additional_info = "Quest Item\nUnique\nDuration: 15 min (real time)\n[q2]Use: Ring to call Shay back to you. (1 Min Cooldown)"},
    [9190] = {name = "Grimoire of Immolate", additional_info = "Classes: Warlock\n[q2]Use: Teaches Immolate (Rank 2).\n[q2]Burns the enemy for 24 Fire damage and then an additional 40 Fire damage over 15 sec.\nSell Price: 2"},
    [9191] = {name = "Grimoire of Curse of Weakness", additional_info = "Classes: Warlock\nRequires Level 4\n[q2]Use: Teaches Curse of Tongues (Rank 1).\n[q2]Forces the target to speak in Demonic, increasing the casting time of all spells by 25%. Only one Curse per Warlock can be active on any one target. Lasts 30 sec.\nSell Price: 10"},
    [9192] = {name = "Grimoire of Corruption", additional_info = "Classes: Warlock\nRequires Level 4\n[q2]Use: Teaches Corruption (Rank 1).\n[q2]Corrupts the target, causing 40 Shadow damage over 12 sec.\nSell Price: 10"},
    [9193] = {name = "Grimoire of Life Tap", additional_info = "Classes: Warlock\nRequires Level 6\n[q2]Use: Teaches Shadow Bolt (Rank 2).\n[q2]Sends a shadowy bolt at the enemy, causing 26 to 32 Shadow damage.\nSell Price: 25"},
    [9194] = {name = "Grimoire of Curse of Agony", additional_info = "Classes: Warlock\nRequires Level 8\n[q2]Use: Teaches Curse of Agony (Rank 1).\n[q2]Curses the target with agony, causing 84 Shadow damage over 24 sec. This damage is dealt slowly at first, and builds up as the Curse reaches its full duration. Only one Curse per Warlock can be active on any one target.\nSell Price: 50"},
    [9195] = {name = "Grimoire of Drain Soul", additional_info = "Classes: Warlock\nRequires Level 10\n[q2]Use: Teaches Fear (Rank 1).\n[q2]Strikes fear in the enemy, causing it to run in fear for up to 10 sec. Damage caused may interrupt the effect. Only 1 target can be feared at a time.\nSell Price: 75"},
    [9197] = {name = "Elixir of Dream Vision", additional_info = "Requires Level 38\n[q2]Use: Gives you a dream vision that lets you explore areas that are too dangerous to explore in person. (3 Sec Cooldown)\nSell Price: 6"},
    [9198] = {name = "Grimoire of Health Funnel", additional_info = "Classes: Warlock\nRequires Level 12\n[q2]Use: Teaches Health Funnel (Rank 1).\n[q2]Gives 12 health to the caster's pet every second for 10 sec as long as the caster channels.\nSell Price: 1 50"},
    [9199] = {name = "Grimoire of Curse of Recklessness", additional_info = "Classes: Warlock\nRequires Level 12\n[q2]Use: Teaches Health Funnel (Rank 1).\n[q2]Gives 12 health to the caster's pet every second for 10 sec as long as the caster channels.\nSell Price: 1 50"},
    [9200] = {name = "Grimoire of Curse of Weakness II", additional_info = "Classes: Warlock\nRequires Level 14\n[q2]Use: Teaches Drain Life (Rank 1).\n[q2]Transfers 10 health every 1 sec from the target to the caster. Lasts 5 sec.\nSell Price: 2 25"},
    [9201] = {name = "Grimoire of Corruption II", additional_info = "Classes: Warlock\nRequires Level 16\n[q2]Use: Teaches Corruption (Rank 2).\n[q2]Corrupts the target, causing 90 Shadow damage over 15 sec.\nSell Price: 3 25"},
    [9202] = {name = "Grimoire of Life Tap II", additional_info = "Classes: Warlock\nRequires Level 18\n[q2]Use: Teaches Create Soulstone.\n[q2]Creates a Minor Soulstone. The Soulstone can be used to store one target's soul. If the target dies while their soul is stored, they will be able to resurrect with 400 health and 700 mana.\n\n Conjured items disappear if logged out for more than 15 minutes.\nSell Price: 5 50\nMinor Soulstone\nConjured Item\nBinds when picked up\nUnique\n[q2]Use: Stores the friendly target's soul. If the target dies while his soul is stored, he will be able to resurrect with 400 health and 700 mana.\nRequires Soul Shard"},
    [9203] = {name = "Grimoire of Ritual of Summoning", additional_info = "Classes: Warlock\nRequires Level 20\n[q2]Use: Teaches Rain of Fire (Rank 1).\n[q2]Calls down a fiery rain to burn enemies in the area of effect for ( 62 * 4) Fire damage over 8 sec.\nSell Price: 7 25"},
