    [10716] = {name = "[q2]Gnomish Shrink Ray", additional_info = "Binds when equipped\nTrinket\nRequires Engineering (205)\n[q2]Use: Shrinks the target reducing their attack power by 250. That's what it usually does anyway..... (5 Min Cooldown)\nSell Price: 7 50"},
