    [10719] = {name = "Mobile Alarm", additional_info = "Requires Engineering (205)\n[q2]Use: Summons an Explosive Sheep which will charge at a nearby enemy and explode for 135 to 165 damage. Lasts for 3 min or until it explodes. (1 Min Cooldown)\nSell Price: 15"},
    [10720] = {name = "[q2]Gnomish Net-o-Matic Projector", additional_info = "Binds when equipped\nTrinket\nRequires Engineering (210)\n[q2]Use: Captures the target in a net for 20 sec. The net has a lot of hooks however and sometimes gets caught in the user's clothing when fired...... (10 Min Cooldown)\nSell Price: 7 50"},
    [10721] = {name = "[q2]Gnomish Harm Prevention Belt", additional_info = "Binds when equipped\nWaist Leather\n66 Armor\n+6 Stamina\nDurability 30 / 30\nRequires Engineering (215)\n[q2]Use: A shield of force protects you from the next 500 damage done over the next 10 min. WARNING: Force Field may overload when struck temporarily removing the wearer from this dimension. (Proc chance: 5%) (1 Hour Cooldown)\nSell Price: 33 17"},
