    [10724] = {name = "[q2]Gnomish Rocket Boots", additional_info = "Binds when equipped\nFeet Cloth\n41 Armor\nDurability 35 / 35\nRequires Engineering (225)\n[q2]Use: These boots significantly increase your run speed for 20 sec. WARNING: Their power supply and gyros do not always function as intended. (15 Min Cooldown)\nSell Price: 46 97"},
    [10725] = {name = "Gnomish Battle Chicken", additional_info = "Binds when picked up\nTrinket\nRequires Engineering (230)\n[q2]Use: Creates a Battle Chicken that will fight for you for 1.50 min or until it is destroyed. (20 Min Cooldown)\nSell Price: 15"},
    [10726] = {name = "[q2]Gnomish Mind Control Cap", additional_info = "Binds when equipped\nHead Cloth\n50 Armor\n+14 Spirit\nDurability 45 / 45\nRequires Engineering (215)\n[q2]Use: Engage in mental combat with a humanoid target to try and control their mind. If all works well, you will control the mind of the target for 30 sec ..... Increased chance of failure when used against targets over level 60. (30 Min Cooldown)\nSell Price: 55 20"},
    [10727] = {name = "Goblin Dragon Gun", additional_info = "Binds when picked up\nTrinket\n[q2]Use: Deals 61 to 69 fire damage for 10 sec to all targets in a cone in front of the engineer using the weapon.  That is unless it explodes..... (5 Min Cooldown)\nSell Price: 20"},
    [10728] = {name = "Pattern: Black Swashbuckler's Shirt", additional_info = "Requires Tailoring (200)\n[q2]Use: Teaches you how to sew a Black Swashbuckler's Shirt.\nSell Price: 3 75\nBlack Swashbuckler's Shirt\nShirt\nSell Price: 15\nRequires Bolt of Silk Cloth (5), Black Dye , Silken Thread"},
