    [12836] = {name = "[q3]Plans: Frostguard", additional_info = "Requires Blacksmithing (300)\n[q2]Use: Teaches you how to make a Frostguard.\nSell Price: 2\n[q3]Frostguard\nBinds when equipped\nOne-Hand Sword\n66 - 124 Damage Speed 2.30\n(41.30 damage per second)\nDurability 90 / 90\nRequires Level 58\n[q2]Chance on hit: Target's movement slowed by 30% and increasing the time between attacks by 25% for 5 sec.\nSell Price: 5 12 52\nRequires Arcanite Bar (18), Blue Sapphire (8), Azerothian Diamond (8), Essence of Water (4), Dense Grinding Stone (2), Enchanted Leather (4)"},
    [12837] = {name = "[q3]Plans: Masterwork Stormhammer", additional_info = "Requires Blacksmithing (300)\n[q2]Use: Teaches you how to make a Masterwork Stormhammer.\nSell Price: 2\n[q3]Masterwork Stormhammer\nBinds when equipped\nOne-Hand Mace\n58 - 108 Damage Speed 2.00\n(41.50 damage per second)\nDurability 90 / 90\nRequires Level 57\n[q2]Chance on hit: Blasts up to 3 targets for 105 to 145 Nature damage.\nSell Price: 5 6 76\nRequires Enchanted Thorium Bar (20), Huge Emerald (8), Large Opal (8), Essence of Earth (6), Enchanted Leather (4)"},
    [12838] = {name = "[q3]Plans: Arcanite Reaper", additional_info = "Requires Blacksmithing (300)\n[q2]Use: Teaches you how to make an Arcanite Reaper.\nSell Price: 2\n[q3]Arcanite Reaper\nBinds when equipped\nTwo-Hand Axe\n153 - 256 Damage Speed 3.80\n(53.82 damage per second)\n+13 Stamina\nDurability 100 / 100\nRequires Level 58\n[q2]Equip: Increases attack power by 62.\nSell Price: 6 57 36\nRequires Arcanite Bar (20), Enchanted Leather (6), Dense Grinding Stone (2)"},
