    [19240] = {name = "Sayge's Fortune #5", additional_info = "Binds when picked up\n[q]\"Someone is speaking well of you.\""},
    [19241] = {name = "Sayge's Fortune #6", additional_info = "Binds when picked up\n[q]\"Be cautious when landing in unfamiliar territory.\""},
