    [19951] = {name = "[q4]Gri'lek's Charm of Might", additional_info = "Binds when picked up\nUnique\nTrinket\nClasses: Warrior\nRequires Level 60\n[q2]Use: Instantly increases your rage by [(300 - 10 * max(0, 80 - 60)) / 10]. (3 Min Cooldown)\n\n[q]Vindicator's Battlegear (0/5)\n[q0]Gri'lek's Charm of Might\nRage of Mugamba\nZandalar Vindicator's Armguards\nZandalar Vindicator's Belt\nZandalar Vindicator's Breastplate\n[q0](2) Set : Increases your block rating by 10.\n(3) Set : Decreases the cooldown of Intimidating Shout by 15 sec.\n(5) Set : Decrease the rage cost of Whirlwind by 3."},
    [19952] = {name = "[q4]Gri'lek's Charm of Valor", additional_info = "Binds when picked up\nUnique\nTrinket\nClasses: Paladin\nRequires Level 60\n[q2]Use: Increases your spell critical strike rating by 140 for 15 sec. (3 Min Cooldown)\n\n[q]Freethinker's Armor (0/5)\n[q0]Gri'lek's Charm of Valor\nHero's Brand\nZandalar Freethinker's Armguards\nZandalar Freethinker's Belt\nZandalar Freethinker's Breastplate\n[q0](2) Set : Restores 5 mana per 5 sec.\n(3) Set : Reduces the casting time of your Holy Light spell by 0.1 sec.\n(5) Set : Increases the duration of all Blessings by 10%."},
    [19953] = {name = "[q4]Renataki's Charm of Beasts", additional_info = "Binds when picked up\nUnique\nTrinket\nClasses: Hunter\nRequires Level 60\n[q2]Use: Instantly clears the cooldowns of Aimed Shot, Multishot, and Volley. (3 Min Cooldown)\n\n[q]Predator's Armor (0/5)\n[q0]Maelstrom's Wrath\nRenataki's Charm of Beasts\nZandalar Predator's Bracers\nZandalar Predator's Belt\nZandalar Predator's Mantle\n[q0](2) Set : Increases attack power by 20.\n(3) Set : Decreases the cooldown of Concussive Shot by 1 sec.\n(5) Set : Increases the duration of Serpent Sting by 3 sec."},
    [19954] = {name = "[q4]Renataki's Charm of Trickery", additional_info = "Binds when picked up\nUnique\nTrinket\nClasses: Rogue\nRequires Level 60\n[q2]Use: Instantly increases your energy by [60 - 4 * max(0, min(15, 80 - 60))]. (3 Min Cooldown)\n\n[q]Madcap's Outfit (0/5)\n[q0]Zandalarian Shadow Mastery Talisman\nRenataki's Charm of Trickery\nZandalar Madcap's Bracers\nZandalar Madcap's Mantle\nZandalar Madcap's Tunic\n[q0](2) Set : Increases attack power by 20.\n(3) Set : Decreases the cooldown of Blind by 5 sec.\n(5) Set : Decrease the energy cost of Eviscerate and Rupture by 5."},
