    [21278] = {name = "[q0]Stormshroud Gloves", additional_info = "Binds when equipped\nHands Leather\n99 Armor\nDurability 35 / 35\nRequires Level 50\n[q2]Equip: Improves critical strike rating by 19.\n[q2]Equip: Improves hit rating by 10.\n\n[q]Stormshroud Armor (0/4)\n[q0]Stormshroud Armor\nStormshroud Pants\nStormshroud Shoulders\nStormshroud Gloves\n[q0](2) Set : 5% chance of dealing 15 to 25 Nature damage on a successful melee attack. (Proc chance: 5%)\n(3) Set : 2% chance on melee attack of restoring 30 energy. (Proc chance: 2%)\n(4) Set : Increases attack power by 14.\nSell Price: 91 26"},
    [21279] = {name = "[q3]Tome of Fireball XII", additional_info = "Classes: Mage\nRequires Level 60\n[q2]Use: Teaches Fireball (Rank 12).\n[q2]Hurls a fiery ball that causes 611 to 776 Fire damage and an additional 76 Fire damage over 8 sec.\nSell Price: 10"},
    [21280] = {name = "[q3]Tome of Arcane Missiles VIII", additional_info = "Classes: Mage\nRequires Level 60\n[q2]Use: Teaches Arcane Missiles (Rank 8).\n[q2]Launches Arcane Missiles at the enemy, causing 234 Arcane damage every 1 sec for 5 sec.\nSell Price: 10"},
    [21281] = {name = "[q3]Grimoire of Shadow Bolt X", additional_info = "Classes: Warlock\nRequires Level 60\n[q2]Use: Teaches Shadow Bolt (Rank 10).\n[q2]Sends a shadowy bolt at the enemy, causing 497 to 554 Shadow damage.\nSell Price: 10"},
    [21282] = {name = "[q3]Grimoire of Immolate VIII", additional_info = "Classes: Warlock\nRequires Level 60\n[q2]Use: Teaches Immolate (Rank 8).\n[q2]Burns the enemy for 299 Fire damage and then an additional 510 Fire damage over 15 sec.\nSell Price: 10"},
    [21283] = {name = "[q3]Grimoire of Corruption VII", additional_info = "Classes: Warlock\nRequires Level 60\n[q2]Use: Teaches Corruption (Rank 7).\n[q2]Corrupts the target, causing 822 Shadow damage over 18 sec.\nSell Price: 10"},
    [21284] = {name = "[q3]Codex of Greater Heal V", additional_info = "Classes: Priest\nRequires Level 60\n[q2]Use: Teaches Greater Heal (Rank 5).\n[q2]A slow casting spell that heals a single target for 2006 to 2235.\nSell Price: 10"},
    [21285] = {name = "[q3]Codex of Renew X", additional_info = "Classes: Priest\nRequires Level 60\n[q2]Use: Teaches Renew (Rank 10).\n[q2]Heals the target for 970 over 15 sec.\nSell Price: 10"},
    [21286] = {name = "[q0]Monster - Axe, 2H Large Double Bladed, Gold", additional_info = "Two-Hand Axe\n2 - 4 Damage Speed 3.30\n(0.91 damage per second)\nDurability 20 / 20\nSell Price: 3"},
    [21287] = {name = "[q3]Codex of Prayer of Healing V", additional_info = "Classes: Priest\nRequires Level 60\n[q2]Use: Teaches Prayer of Healing (Rank 5).\n[q2]A powerful prayer heals the friendly target's party members within 30 yards for 1019 to 1076.\nSell Price: 10"},
    [21288] = {name = "[q3]Libram: Blessing of Wisdom VI", additional_info = "Classes: Paladin\nRequires Level 60\n[q2]Use: Teaches Blessing of Wisdom (Rank 6).\n[q2]Places a Blessing on the friendly target, restoring 33 mana every 5 seconds for 10 min. Players may only have one Blessing on them per Paladin at any one time.\nSell Price: 10"},
    [21289] = {name = "[q3]Libram: Blessing of Might VII", additional_info = "Classes: Paladin\nRequires Level 60\n[q2]Use: Teaches Blessing of Might (Rank 7).\n[q2]Places a Blessing on the friendly target, increasing attack power by 232 for 10 min. Players may only have one Blessing on them per Paladin at any one time.\nSell Price: 10"},
    [21290] = {name = "[q3]Libram: Holy Light IX", additional_info = "Classes: Paladin\nRequires Level 60\n[q2]Use: Teaches Holy Light (Rank 9).\n[q2]Heals a friendly target for 2063 to 2295.\nSell Price: 10"},
    [21291] = {name = "[q3]Tablet of Healing Wave X", additional_info = "Classes: Shaman\nRequires Level 60\n[q2]Use: Teaches Healing Wave (Rank 10).\n[q2]Heals a friendly target for 1647 to 1878.\nSell Price: 10"},
    [21292] = {name = "[q3]Tablet of Strength of Earth Totem V", additional_info = "Classes: Shaman\nRequires Level 60\n[q2]Use: Teaches Strength of Earth Totem (Rank 5).\n[q2]Summons a Strength of Earth Totem with 5 health at the feet of the caster. The totem increases the strength and agility of all party and raid members within 30 yards by 77. Lasts 5 min.\nSell Price: 10"},
    [21293] = {name = "[q3]Tablet of Grace of Air Totem III", additional_info = "Classes: Shaman\nRequires Level 60\n[q2]Use: Teaches Grace of Air Totem (Rank 3).\nSell Price: 10"},
    [21294] = {name = "[q3]Book of Healing Touch XI", additional_info = "Classes: Druid\nRequires Level 60\n[q2]Use: Teaches Healing Touch (Rank 11).\n[q2]Heals a friendly target for 1975 to 2325.\nSell Price: 10"},
    [21295] = {name = "[q3]Book of Starfire VII", additional_info = "Classes: Druid\nRequires Level 60\n[q2]Use: Teaches Starfire (Rank 7).\n[q2]Causes 711 to 836 Arcane damage to the target.\nSell Price: 10"},
    [21296] = {name = "[q3]Book of Rejuvenation XI", additional_info = "Classes: Druid\nRequires Level 60\n[q2]Use: Teaches Rejuvenation (Rank 11).\n[q2]Heals the target for [222 * (5 + 0 ) * ( ( ( ( 1 ) ) ) )] over 15 sec.\nSell Price: 10"},
    [21297] = {name = "[q3]Manual of Heroic Strike IX", additional_info = "Classes: Warrior\nRequires Level 60\n[q2]Use: Teaches Heroic Strike (Rank 9).\n[q2]A strong attack that increases melee damage by 201 and causes a high amount of threat.\nSell Price: 10"},
    [21298] = {name = "[q3]Manual of Battle Shout VII", additional_info = "Classes: Warrior\nRequires Level 60\n[q2]Use: Teaches Battle Shout (Rank 7).\n[q2]The warrior shouts, increasing attack power of all raid and party members within 30 yards by 240. Lasts 2 min.\nSell Price: 10"},
    [21299] = {name = "[q3]Manual of Revenge VI", additional_info = "Classes: Warrior\nRequires Level 60\n[q2]Use: Teaches Revenge (Rank 6).\n[q2]Instantly counterattack an enemy for (723 + Attack power * 0.310) to (883 + Attack power * 0.310) damage.  Revenge is only usable after the warrior blocks, dodges or parries an attack.\nSell Price: 10"},
    [21300] = {name = "[q3]Handbook of Backstab IX", additional_info = "Classes: Rogue\nRequires Level 60\n[q2]Use: Teaches Backstab (Rank 9).\n[q2]Backstab the target, causing 150% weapon damage plus 225 to the target. Must be behind the target. Requires a dagger in the main hand. Awards 1 combo point.\nSell Price: 10"},
    [21301] = {name = "Green Helper Box", additional_info = "Binds when used\n[q2]Use: Teaches you how to summon this companion.\n[q2]Right Click to summon and dismiss your Father Winter's Helper. Requires a Snowball to summon."},
    [21302] = {name = "[q3]Handbook of Deadly Poison V", additional_info = "Classes: Rogue\nRequires Level 60\n[q2]Use: Teaches Deadly Poison (Rank 5).\nSell Price: 10"},
    [21303] = {name = "[q3]Handbook of Feint V", additional_info = "Classes: Rogue\nRequires Level 60\n[q2]Use: Teaches Feint (Rank 5).\n[q2]Performs a feint, causing no damage but lowering your threat by a large amount, making the enemy less likely to attack you.\nSell Price: 10"},
    [21304] = {name = "[q3]Guide: Multi-Shot V", additional_info = "Classes: Hunter\nRequires Level 60\n[q2]Use: Teaches Multi-Shot (Rank 5).\n[q2]Fires several missiles, hitting 3 targets for an additional 150 damage.\nSell Price: 10"},
    [21305] = {name = "Red Helper Box", additional_info = "Binds when used\n[q2]Use: Teaches you how to summon this companion.\n[q2]Right Click to summon and dismiss your Winter's Little Helper. Requires a Snowball to summon."},
    [21306] = {name = "[q3]Guide: Serpent Sting IX", additional_info = "Classes: Hunter\nRequires Level 60\n[q2]Use: Teaches Serpent Sting (Rank 9).\n[q2]Stings the target, causing (Ranged attack power * 0.2 + 111 * 15 / 3) Nature damage over 15 sec. Only one Sting per Hunter can be active on any one target.\nSell Price: 10"},
    [21307] = {name = "[q3]Guide: Aspect of the Hawk VII", additional_info = "Classes: Hunter\nRequires Level 60\n[q2]Use: Teaches Aspect of the Hawk (Rank 7).\n[q2]The hunter takes on the aspects of a hawk, increasing ranged attack power by 120. Only one Aspect can be active at a time.\nSell Price: 10"},
    [21308] = {name = "Jingling Bell", additional_info = "Binds when used\n[q2]Use: Teaches you how to summon this companion.\n[q2]Right Click to summon and dismiss your Winter Reindeer. Requires a Snowball to summon."},
    [21309] = {name = "Snowman Kit", additional_info = "Binds when used\n[q2]Use: Teaches you how to summon this companion.\n[q2]Right Click to summon and dismiss your Tiny Snowman. Requires a Snowball to summon."},
    [21310] = {name = "Gaily Wrapped Present", additional_info = "Binds when picked up\n[q2]<Right Click to Open>"},
    [21311] = {name = "[q2]Earth Warder's Vest", additional_info = "Binds when picked up\nChest Cloth\n63 Armor\n+13 Intellect\nDurability 70 / 70\n[q2]Equip: Restores 8 mana per 5 sec.\nSell Price: 84 73"},
    [21312] = {name = "[q2]Belt of the Den Watcher", additional_info = "Binds when picked up\nWaist Mail\n148 Armor\n+6 Stamina\nDurability 35 / 35\n[q2]Equip: Increases attack power by 24.\nSell Price: 63 77"},
