    [21314] = {name = "Metzen's Letters and Notes", additional_info = "Binds when picked up\nUnique\n[q]\"A collection of information related to the whereabouts of Metzen the reindeer, including both ransom notes.\"\n[q2]<Right Click to Read>"},
    [21315] = {name = "Smokywood Satchel", additional_info = "Binds when picked up\nUnique\n[q]\"Inside are the things you will need to rescue Metzen the Reindeer!\"\n[q2]<Right Click to Open>"},
    [21316] = {name = "[q2]Leggings of the Ursa", additional_info = "Binds when picked up\nLegs Plate\n459 Armor\n+17 Strength\nDurability 85 / 85\n[q2]Equip: Increases your critical strike rating by 14.\nSell Price: 2 17 13"},
    [21317] = {name = "[q2]Helm of the Pathfinder", additional_info = "Binds when picked up\nHead Leather\n117 Armor\n+17 Stamina\nDurability 50 / 50\n[q2]Equip: Increases your critical strike rating by 14.\nSell Price: 1 16 75"},
