    [21320] = {name = "[q2]Vest of the Den Watcher", additional_info = "Binds when picked up\nChest Mail\n313 Armor\n+20 Agility\n+12 Stamina\nDurability 100 / 100\nSell Price: 2 24 97"},
    [21321] = {name = "[q3]Red Qiraji Resonating Crystal", additional_info = "Binds when picked up\nUnique\nMount\nRequires Level 40\nRequires Riding (75)\n[q2]Use: Teaches you how to summon this mount. This mount may only be summoned in the Temple of Ahn'Qiraj.\n[q2]Emits a high frequency sound, forcing a silithid tank to burrow out from its home beneath the Temple of Ahn'Qiraj. The silithid is obedient to the summoner and can be used as a mount within the Temple of Ahn'Qiraj. Any hostile action towards the rider forces the tank underground."},
    [21322] = {name = "[q2]Ursa's Embrace", additional_info = "Binds when picked up\nChest Plate\n552 Armor\n+17 Agility\nDurability 115 / 115\n[q2]Equip: Increases defense rating by 15.\nSell Price: 2 64 39"},
    [21323] = {name = "[q3]Green Qiraji Resonating Crystal", additional_info = "Binds when picked up\nUnique\nMount\nRequires Level 40\nRequires Riding (75)\n[q2]Use: Teaches you how to summon this mount. This mount may only be summoned in the Temple of Ahn'Qiraj.\n[q2]Emits a high frequency sound, forcing a silithid tank to burrow out from its home beneath the Temple of Ahn'Qiraj. The silithid is obedient to the summoner and can be used as a mount within the Temple of Ahn'Qiraj. Any hostile action towards the rider forces the tank underground."},
    [21324] = {name = "[q3]Yellow Qiraji Resonating Crystal", additional_info = "Binds when picked up\nUnique\nMount\nRequires Level 40\nRequires Riding (75)\n[q2]Use: Teaches you how to summon this mount. This mount may only be summoned in the Temple of Ahn'Qiraj.\n[q2]Emits a high frequency sound, forcing a silithid tank to burrow out from its home beneath the Temple of Ahn'Qiraj. The silithid is obedient to the summoner and can be used as a mount within the Temple of Ahn'Qiraj. Any hostile action towards the rider forces the tank underground."},
    [21325] = {name = "[q2]Mechanical Greench", additional_info = "Binds when picked up\nDuration: 10 days (real time)\n[q2]Use: Summons a mechanical Greench that will protect you for 10 min. (10 Min Cooldown)\n3 Charges"},
