    [21940] = {name = "[q2]Design: Golden Hare", additional_info = "Requires Jewelcrafting (200)\n[q2]Use: Teaches you how to craft a Golden Hare.\nSell Price: 12 50\n[q2]Figurine - Golden Hare\nBinds when picked up\nUnique\nTrinket\nRequires Level 35\nRequires Jewelcrafting (200)\n[q2]Equip: Run speed increased slightly.\n[q2]Use: Increased speed by 30% and prevents new snares from landing on the user for 6 sec. (20 Min Cooldown)\nSell Price: 15\nRequires Gold Bar (6), Citrine (2)"},
    [21941] = {name = "Design: Black Pearl Panther", additional_info = "Requires Jewelcrafting (215)\n[q2]Use: Teaches you how to craft a Black Pearl Panther.\nSell Price: 12 50\n[q2]Figurine - Black Pearl Panther\nBinds when picked up\nUnique\nTrinket\nRequires Level 38\nRequires Jewelcrafting (215)\n[q2]Equip: Increases your stealth slightly.\n[q2]Use: Increases attack power by 90 for 15 sec. (5 Min Cooldown)\nSell Price: 15\nRequires Black Pearl (4), Flask of Mojo (4)"},
    [21942] = {name = "Design: Ruby Crown of Restoration", additional_info = "Requires Jewelcrafting (225)\n[q2]Use: Teaches you how to craft a Ruby Crown of Restoration.\nSell Price: 15\n[q3]Ruby Crown of Restoration\nBinds when equipped\nHead Cloth\n53 Armor\n+9 Intellect\nDurability 50 / 50\nRequires Level 40\n[q2]Equip: Increases spell power by 26.\nSell Price: 59 89\nRequires Star Ruby (2), Black Pearl (2), Truesilver Bar (4), Thorium Setting (4), Greater Mana Potion (4)"},
    [21943] = {name = "Design: Truesilver Crab", additional_info = "Requires Jewelcrafting (225)\n[q2]Use: Teaches you how to craft a Truesilver Crab.\nSell Price: 15\n[q2]Figurine - Truesilver Crab\nBinds when picked up\nUnique\nTrinket\nRequires Level 40\nRequires Jewelcrafting (225)\n[q2]Equip: Increases defense rating by 5.\n[q2]Use: Reduces melee damage taken by 20 for 20 sec. (5 Min Cooldown)\nSell Price: 15\nRequires Aquamarine (2), Truesilver Bar (4), Core of Earth (2), Globe of Water (2), Flask of Mojo (4)"},
    [21944] = {name = "[q2]Design: Truesilver Boar", additional_info = "Requires Jewelcrafting (235)\n[q2]Use: Teaches you how to craft a Truesilver Boar.\nSell Price: 18 75\n[q2]Figurine - Truesilver Boar\nBinds when picked up\nUnique\nTrinket\nRequires Level 42\nRequires Jewelcrafting (235)\n[q2]Equip: Increases attack power by 8.\n[q2]Use: Summons the Truesilver Boar to fight for you for 30 seconds. (15 Min Cooldown)\nSell Price: 15\nRequires Star Ruby (2), Truesilver Bar (4), Heart of Fire (2), Breath of Wind (2), Flask of Mojo (4)"},
    [21945] = {name = "[q2]Design: The Aquamarine Ward", additional_info = "Requires Jewelcrafting (245)\n[q2]Use: Teaches you how to craft The Aquamarine Ward.\nSell Price: 18 75\n[q2]The Aquamarine Ward\nBinds when equipped\nUnique-Equipped\nFinger\nRequires Level 44\n[q2]Equip: Increases your dodge rating by 12.\nSell Price: 43 7\nRequires Aquamarine , Thorium Setting"},
