    [23632] = {name = "[q4]Plans: Felsteel Reaper", additional_info = "Requires Blacksmithing (365)\n[q2]Use: Teaches you how to make a Felsteel Reaper.\nSell Price: 12\n[q4]Felsteel Reaper\nBinds when equipped\nTwo-Hand Axe\n295 - 443 Damage Speed 3.40\n(108.53 damage per second)\nDurability 120 / 120\nRequires Level 70\n[q2]Equip: Improves critical strike rating by 30.\n[q2]Equip: Increases attack power by 112.\nSell Price: 13 62 2\nRequires Khorium Bar (10), Felsteel Bar (10), Primal Might (8), Primal Nether (2)"},
    [23633] = {name = "[q4]Plans: Runic Hammer", additional_info = "Requires Blacksmithing (365)\n[q2]Use: Teaches you how to make a Runic Hammer.\nSell Price: 12\n[q4]Runic Hammer\nBinds when equipped\nOne-Hand Mace\n140 - 261 Damage Speed 2.40\n(83.54 damage per second)\n+16 Stamina\nDurability 105 / 105\nRequires Level 70\n[q0]Increases attack power by 401 in Cat, Bear, Dire Bear, and Moonkin forms only.\n[q2]Equip: Increases attack power by 50.\nSell Price: 10 93 50\nRequires Khorium Bar (10), Felsteel Bar (10), Primal Might (8), Primal Nether (2)"},
    [23634] = {name = "[q4]Plans: Fel Hardened Maul", additional_info = "Requires Blacksmithing (365)\n[q2]Use: Teaches you how to make a Fel Hardened Maul.\nSell Price: 12\n[q4]Fel Hardened Maul\nBinds when equipped\nTwo-Hand Mace\n286 - 430 Damage Speed 3.30\n(108.48 damage per second)\n+50 Strength\n+46 Stamina\nDurability 120 / 120\nRequires Level 70\n[q0]Increases attack power by 751 in Cat, Bear, Dire Bear, and Moonkin forms only.\n[q2]Equip: Improves critical strike rating by 21.\nSell Price: 13 76 87\nRequires Khorium Bar (10), Felsteel Bar (10), Primal Might (8), Primal Nether (2)"},
    [23635] = {name = "[q4]Plans: Eternium Runed Blade", additional_info = "Requires Blacksmithing (365)\n[q2]Use: Teaches you how to make an Eternium Runed Blade.\nSell Price: 12\n[q4]Eternium Runed Blade\nBinds when equipped\nMain Hand Dagger\n28 - 114 Damage Speed 1.70\n(41.76 damage per second)\n+19 Intellect\nDurability 75 / 75\nRequires Level 70\n[q2]Equip: Improves critical strike rating by 21.\n[q2]Equip: Increases spell power by 168.\nSell Price: 10 53 75\nRequires Khorium Bar (10), Hardened Adamantite Bar (4), Eternium Bar (10), Primal Might (8), Primal Nether (2)"},
    [23636] = {name = "[q4]Plans: Dirge", additional_info = "Requires Blacksmithing (365)\n[q2]Use: Teaches you how to make Dirge.\nSell Price: 12\n[q4]Dirge\nBinds when equipped\nOne-Hand Dagger\n81 - 152 Damage Speed 1.40\n(83.21 damage per second)\nDurability 75 / 75\nRequires Level 70\n[q0]Increases attack power by 397 in Cat, Bear, Dire Bear, and Moonkin forms only.\n[q2]Equip: Improves critical strike rating by 20.\n[q2]Equip: Increases attack power by 40.\nSell Price: 10 57 63\nRequires Khorium Bar (10), Felsteel Bar (10), Primal Might (8), Primal Nether (2)"},
    [23637] = {name = "[q4]Plans: Hand of Eternity", additional_info = "Requires Blacksmithing (365)\n[q2]Use: Teaches you how to make Hand of Eternity.\nSell Price: 12\n[q4]Hand of Eternity\nBinds when equipped\nMain Hand Mace\n35 - 131 Damage Speed 1.90\n(43.68 damage per second)\n+20 Intellect\nDurability 105 / 105\nRequires Level 70\n[q2]Equip: Restores 9 mana per 5 sec.\n[q2]Equip: Increases spell power by 168.\nSell Price: 10 61 63\nRequires Khorium Bar (10), Hardened Adamantite Bar (4), Eternium Bar (10), Primal Might (8), Primal Nether (4)"},
    [23638] = {name = "Plans: Lesser Ward of Shielding", additional_info = "Requires Blacksmithing (340)\n[q2]Use: Teaches you how to make a Lesser Ward of Shielding.\nSell Price: 1 50\nLesser Ward of Shielding\nRequires Level 55\n[q2]Use: Applies the Lesser Ward of Shielding to your shield. This ward absorbs up to 1000 points of damage before it fails.\nSell Price: 15\nRequires Adamantite Bar"},
    [23639] = {name = "[q3]Plans: Greater Ward of Shielding", additional_info = "Binds when picked up\nRequires Blacksmithing (375)\n[q2]Use: Teaches you how to make a Greater Ward of Shielding.\nSell Price: 7 50\nGreater Ward of Shielding\nRequires Level 55\n[q2]Use: Applies the Greater Ward of Shielding to your shield. This ward absorbs up to 4000 points of damage before it fails.\nSell Price: 12 50\nRequires Eternium Bar"},
    [23642] = {name = "Sha'naar Relic", additional_info = "Quest Item"},
    [23643] = {name = "Purifying Earth", additional_info = "Quest Item\n[q]\"This clump of earth, found at the core of a boulderkin, radiates a sense of purity absent from the rest of the elemental's body.\""},
    [23644] = {name = "Crate of Reagents", additional_info = "Binds when picked up\nUnique\n[q]\"A container full of the reagents needed to make a trial dose of Magistrix Elosai's tonic.\""},
    [23645] = {name = "Seer's Relic", additional_info = "Quest Item\n[q2]Use: Bestows seer's vision upon the wielder."},
    [23646] = {name = "Shipment of Rare Crystals", additional_info = "Quest Item\nUnique\n[q]\"A plain, unmarked box containing valuable crystals from the Azurelode Mine.\""},
    [23654] = {name = "Draenei Fishing Net", additional_info = "Binds when picked up\nUnique\n[q2]Use: Casts your draenei fishing net into a school of red snapper."},
    [23655] = {name = "Elven Manacles", additional_info = "Quest Item\n[q2]Use: Apply manacles to a wounded Bloodscalp Shaman to subdue and capture it.\n[q]\"A wicked-looking restraint device of exquisite craftsmanship.\""},
    [23657] = {name = "Dawn Runner Cargo", additional_info = "Quest Item\nUnique\n[q]\"The remaining cargo from the holds of the Dawn Runner.\""},
    [23658] = {name = "Advisor's Pack", additional_info = "Quest Item\n[q]\"A brightly-colored silken bag. It looks to have spent some time as a chewtoy for some Dark Iron dwarf's pet.\""},
    [23659] = {name = "Fel-Tainted Morsels", additional_info = "Quest Item\nUnique\n[q2]Use: Feeds the captured animal. (5 Sec Cooldown)"},
    [23660] = {name = "Advisor's Rapier", additional_info = "Quest Item\nUnique\n[q]\"A finely crafted elven sword, destined for the slag heap of a Dark Iron smithy.\""},
    [23661] = {name = "Mark of the Lightbringer", additional_info = "Quest Item\nUnique\n[q]\"The holy symbol carried by Uther Lightbringer during his final days.\""},
