    [23794] = {name = "[q2]Permanent Sheen of Zanza", additional_info = "Binds when picked up\nUnique\nRequires Level 55\n[q2]Use: Increases the chance that the player will reflect hostile spells cast on them by 3% for 2 hrs. Will automatically reflect the first offensive spell cast against the user. Only one type of Zanza potion may be active at any given time.\n[q]\"Blessed with the mojo of Zanza!\""},
    [23795] = {name = "[q2]Permanent Spirit of Zanza", additional_info = "Binds when picked up\nUnique\nRequires Level 55\n[q2]Use: Increases the player's Spirit by 50 and Stamina by 50 for 2 hrs. You can only have the effect of one Zanza potion at a time.\n[q]\"Blessed with the mojo of Zanza!\""},
    [23796] = {name = "[q2]Permanent Swiftness of Zanza", additional_info = "Binds when picked up\nUnique\nRequires Level 55\n[q2]Use: Increases the player's run speed by 20% for 2 hrs. You can only have the effect of one Zanza potion at a time.\n[q]\"Blessed with the mojo of Zanza!\""},
    [23797] = {name = "Diabolical Plans", additional_info = "Binds when picked up\nUnique\nThis Item Begins a Quest\nRequires Level 27"},
    [23798] = {name = "Diabolical Plans", additional_info = "Quest Item\nUnique\nRequires Level 27\n[q]\"The ink appears to be dried blood.\"\n[q2]<Right Click to Read>"},
    [23799] = {name = "Schematic: Adamantite Rifle", additional_info = "Requires Engineering (350)\n[q2]Use: Teaches you how to make an Adamantite Rifle.\nSell Price: 2\n[q2]Adamantite Rifle\nBinds when equipped\nRanged Gun\n126 - 234 Damage Speed 3.00\n(60.00 damage per second)\n+12 Agility\nDurability 65 / 65\nRequires Level 69\n[q2]Equip: Increases attack power by 22.\nSell Price: 5 57 25\nRequires Fel Iron Casing (3), Adamantite Frame (2), Handful of Fel Iron Bolts (4)"},
    [23800] = {name = "[q3]Schematic: Felsteel Boomstick", additional_info = "Binds when picked up\nRequires Engineering (360)\n[q2]Use: Teaches you how to make a Felsteel Boomstick.\nSell Price: 2 50\n[q3]Felsteel Boomstick\nBinds when equipped\nRanged Gun\n104 - 194 Damage Speed 2.40\n(62.08 damage per second)\n+12 Stamina\nDurability 75 / 75\nRequires Level 70\n[q2]Equip: Improves critical strike rating by 13.\nSell Price: 6 24 13\nRequires Hardened Adamantite Tube , Felsteel Stabilizer (4), Handful of Fel Iron Bolts (4)"},
    [23801] = {name = "Bristlelimb Key", additional_info = "Quest Item\n[q2]Use: Unlocks Bristlelimb cages."},
    [23802] = {name = "[q3]Schematic: Ornate Khorium Rifle", additional_info = "Requires Engineering (375)\n[q2]Use: Teaches you how to make an Ornate Khorium Rifle.\nSell Price: 3 75\n[q3]Ornate Khorium Rifle\nBinds when equipped\nRanged Gun\n144 - 268 Damage Speed 3.10\n(66.45 damage per second)\n+14 Agility\nDurability 75 / 75\nRequires Level 70\n[q2]Equip: Improves hit rating by 13.\nSell Price: 6 63 12\nRequires Hardened Adamantite Tube (2), Khorium Bar (12), Handful of Fel Iron Bolts (4), Noble Topaz (2)"},
    [23803] = {name = "Schematic: Cogspinner Goggles", additional_info = "Requires Engineering (340)\n[q2]Use: Teaches you how to make Cogspinner Goggles.\nSell Price: 1 50\n[q3]Cogspinner Goggles\nBinds when equipped\nHead Leather\n220 Armor\n[q2]<Random enchantment>\nDurability 60 / 60\nRequires Engineering (340)\nSell Price: 2 96 67\nRequires Heavy Knothide Leather (4), Blood Garnet (2), Arcane Dust (8)"},
    [23804] = {name = "[q3]Schematic: Power Amplification Goggles", additional_info = "Requires Engineering (340)\n[q2]Use: Teaches you how to make Power Amplification Goggles.\nSell Price: 2\n[q3]Power Amplification Goggles\nBinds when equipped\nHead Cloth\n100 Armor\n+46 Stamina\nDurability 50 / 50\nRequires Engineering (340)\n[q2]Equip: Improves critical strike rating by 31.\n[q2]Equip: Increases spell power by 36.\nSell Price: 2 5 34\nRequires Heavy Knothide Leather (4), Flame Spessarite (2), Arcane Dust (8)"},
    [23805] = {name = "Schematic: Ultra-Spectropic Detection Goggles", additional_info = "Requires Engineering (350)\n[q2]Use: Teaches you how to make Ultra-Spectropic Detection Goggles.\nSell Price: 2\n[q3]Ultra-Spectropic Detection Goggles\nBinds when equipped\nHead Cloth\n124 Armor\n+36 Stamina\nDurability 50 / 50\nRequires Engineering (350)\n[q2]Equip: Improves critical strike rating by 24.\n[q2]Equip: Improves hit rating by 24.\n[q2]Equip: Improves your resilience rating by 24.\n[q2]Equip: Improves haste rating by 24.\n[q2]Use: Allows you to look far into the distance.\nSell Price: 2 53 24\nRequires Heavy Knothide Leather (4), Khorium Bar (2), Deep Peridot (2), Small Prismatic Shard (2)"},
    [23806] = {name = "[q3]Schematic: Hyper-Vision Goggles", additional_info = "Binds when picked up\nRequires Engineering (360)\n[q2]Use: Teaches you how to make Hyper-Vision Goggles.\nSell Price: 4\n[q3]Hyper-Vision Goggles\nBinds when equipped\nHead Leather\n232 Armor\nDurability 60 / 60\nRequires Engineering (360)\n[q2]Equip: Improves hit rating by 23.\n[q2]Equip: Increases attack power by 84.\n[q2]Use: Increases your stealth detection for 15 sec. (2 Min Cooldown)\nSell Price: 3 17 74\nRequires Heavy Knothide Leather (4), Khorium Bar (2), Nightseye (2), Large Prismatic Shard (2)"},
    [23807] = {name = "Schematic: Adamantite Scope", additional_info = "Requires Engineering (335)\n[q2]Use: Teaches you how to make an Adamantite Scope.\nSell Price: 1 50\n[q2]Adamantite Scope\nRequires Level 55\n[q2]Use: Attaches a permanent scope to a bow or gun that increases its damage by 10.\n\n Attaching this scope to a ranged weapon causes it to become soulbound.\nSell Price: 25\nRequires Adamantite Bar (8), Golden Draenite (2)"},
    [23808] = {name = "[q3]Schematic: Khorium Scope", additional_info = "Binds when picked up\nRequires Engineering (360)\n[q2]Use: Teaches you how to make a Khorium Scope.\nSell Price: 4\n[q3]Khorium Scope\nRequires Level 55\n[q2]Use: Attaches a permanent scope to a bow or gun that increases its damage by 12.\nSell Price: 25\nRequires Hardened Adamantite Tube , Khorium Bar (4), Dawnstone (2)"},
    [23809] = {name = "[q3]Schematic: Stabilized Eternium Scope", additional_info = "Binds when picked up\nRequires Engineering (375)\n[q2]Use: Teaches you how to make a Stabilized Eternium Scope.\nSell Price: 1 50\n[q3]Stabilized Eternium Scope\nRequires Level 60\n[q2]Use: Attaches a permanent scope to a bow or gun that increases its critical strike rating by 28.\n\n Attaching this scope to a ranged weapon causes it to become soulbound.\nSell Price: 2\nRequires Hardened Adamantite Tube (2), Felsteel Stabilizer (6), Star of Elune (2)"},
    [23810] = {name = "[q2]Schematic: Crashin' Thrashin' Robot", additional_info = "Requires Engineering (325)\n[q2]Use: Teaches you how to make a Crashin' Thrashin' Robot.\nSell Price: 2\n[q2]Crashin' Thrashin' Robot\nBinds when used\nToy\n[q2]Use: Right Click to summon a robot pet that will fight other fighting robots. (3 Min Cooldown)\nSell Price: 50\nRequires Adamantite Frame , Fel Iron Casing (2), Gold Power Core , Handful of Fel Iron Bolts (2)"},
    [23811] = {name = "Schematic: White Smoke Flare", additional_info = "Requires Engineering (335)\n[q2]Use: Teaches you how to make a White Smoke Flare.\nSell Price: 1 50\nWhite Smoke Flare\n[q2]Use: Throw a white smoke flare at a specific location that lasts for 5 min. (5 Sec Cooldown)\nSell Price: 2 50\nRequires Elemental Blasting Powder , Netherweave Cloth"},
    [23812] = {name = "Schematic: Red Smoke Flare", additional_info = "Binds when picked up\nRequires Engineering (335)\n[q2]Use: Teaches you how to make a Red Smoke Flare.\nSell Price: 1 50\nRed Smoke Flare\n[q2]Use: Throw a red smoke flare at a specific location that lasts for 5 min. (5 Sec Cooldown)\nSell Price: 2 50\nRequires Elemental Blasting Powder , Netherweave Cloth , Red Dye"},
    [23813] = {name = "Schematic: Blue Smoke Flare", additional_info = "Binds when picked up\nRequires Engineering (335)\n[q2]Use: Teaches you how to make a Blue Smoke Flare.\nSell Price: 1 50\nBlue Smoke Flare\n[q2]Use: Throw a blue smoke flare at a specific location that lasts for 5 min. (5 Sec Cooldown)\nSell Price: 2 50\nRequires Elemental Blasting Powder , Netherweave Cloth , Blue Dye"},
    [23814] = {name = "Schematic: Green Smoke Flare", additional_info = "Binds when picked up\nRequires Engineering (335)\nRequiresCenarion Expedition\n- Friendly\n[q2]Use: Teaches you how to make a Green Smoke Flare.\nSell Price: 1 50\nGreen Smoke Flare\n[q2]Use: Throw a green smoke flare at a specific location that lasts for 5 min. (5 Sec Cooldown)\nSell Price: 2 50\nRequires Elemental Blasting Powder , Netherweave Cloth , Green Dye"},
    [23815] = {name = "Schematic: Adamantite Shell Machine", additional_info = "Requires Engineering (335)\n[q2]Use: Teaches you how to make an Adamantite Shell Machine.\nSell Price: 1 50\nAdamantite Shell Machine\n[q2]Use: Creates 200 Adamantite Shells.\n5 Charges\n[q]\"Warning: Contains Explosives.\"\nSell Price: 62 50\nRequires Adamantite Bar , Elemental Blasting Powder (2), Simple Wood (4)"},
    [23816] = {name = "Schematic: Fel Iron Toolbox", additional_info = "Requires Engineering (325)\n[q2]Use: Teaches you how to make a Fel Iron Toolbox.\nSell Price: 1\n[q2]Fel Iron Toolbox\nBinds when equipped\n24 Slot Engineering Bag\nSell Price: 3\nRequires Fel Iron Casing , Fel Iron Bar (5), Handful of Fel Iron Bolts (2)"},
    [23817] = {name = "Schematic: Titanium Toolbox", additional_info = "Requires Engineering (405)\n[q2]Use: Teaches you how to make a Titanium Toolbox.\nSell Price: 2\n[q3]Titanium Toolbox\nBinds when equipped\n32 Slot Engineering Bag\n[q]\"Filled with small compartments that are perfect for storing engineering devices.\"\nSell Price: 3\nRequires Saronite Bar (8), Titanium Bar (8), Handful of Cobalt Bolts (4)"},
    [23818] = {name = "Stillpine Furbolg Language Primer", additional_info = "Binds when picked up\nUnique\n[q2]Use: Teaches the user to better understand Stillpine furbolg symbols.\n[q]\"The primer provides translations for the basic symbology of the furbolg language.\""},
    [23819] = {name = "Elemental Seaforium Charge", additional_info = "Requires Engineering (350)\n[q2]Use: Blasts open all but the mightiest of locked doors and chests.\nSell Price: 60"},
    [23820] = {name = "[q2]Critter Enlarger", additional_info = "Requires Engineering (325)\n[q2]Use: Enlarges a critter to twice its normal size. (15 Sec Cooldown)\n[q]\"The practical uses for this device are nearly limitless.\"\nSell Price: 1 50"},
    [23821] = {name = "Zapthrottle Mote Extractor", additional_info = "Unique\nRequires Engineering (305)\n[q2]Use: Extracts gas from a nearby gas cloud.\n[q2]Shows the location of nearby gas clouds on the minimap while the mote extractor remains in your inventory.\nSell Price: 1 50"},
    [23822] = {name = "Healing Potion Injector", additional_info = "Requires Level 55\n[q2]Use: Restores 1500 to 2500 health. Increased effect for engineers! (1 Min Cooldown)\n20 Charges\n[q]\"They just don't make 'em like this anymore...\"\nSell Price: 10"},
    [23823] = {name = "Mana Potion Injector", additional_info = "Requires Level 55\n[q2]Use: Restores 1800 to 3000 mana. Increased effect for engineers! (1 Min Cooldown)\n20 Charges\n[q]\"They just don't make 'em like this anymore...\"\nSell Price: 10"},
    [23824] = {name = "[q3]Rocket Boots Xtreme", additional_info = "Binds when equipped\nFeet Leather\n196 Armor\nDurability 50 / 50\nRequires Engineering (330)\n[q2]Equip: Increases attack power by 80.\n[q2]Use: Engage the rocket boots to greatly increase your speed. (5 Min Cooldown)\nSell Price: 3 27 34"},
    [23825] = {name = "[q3]Nigh Invulnerability Belt", additional_info = "Binds when equipped\nWaist Cloth\n[q2]223 Armor\n+21 Stamina\nDurability 30 / 30\nRequires Engineering (350)\n[q2]Use: Protects you with a shield of force that stops 4000 damage for 8 sec. (5 Min Cooldown)\n[q]\"Protection not always valid. In RARE cases wearer may take additional damage.\"\nSell Price: 1 70 96"},
    [23826] = {name = "The Bigger One", additional_info = "Requires Engineering (325)\n[q2]Use: Inflicts 600 to 1000 Fire damage and incapacitates targets for 5 sec in a 10 yard radius. Any damage will break the effect. Unreliable against targets higher than level 80. (1 Min Cooldown)\nSell Price: 30"},
    [23827] = {name = "Super Sapper Charge", additional_info = "Requires Engineering (340)\n[q2]Use: Explodes when triggered, dealing 900 to 1500 Fire damage to all enemies nearby and 675 to 1125 damage to you. (5 Min Cooldown)\nSell Price: 40"},
    [23828] = {name = "[q4]Gnomish Power Goggles", additional_info = "Binds when picked up\nHead Cloth\n132 Armor\n+21 Intellect\nDurability 60 / 60\nRequires Engineering (375)\nRequiresGnomish Engineer\n[q2]Equip: Increases spell power by 59.\n[q2]Equip: Increases your critical strike rating by 28.\nSell Price: 3 5 47"},
    [23829] = {name = "[q4]Gnomish Battle Goggles", additional_info = "Binds when picked up\nHead Leather\n249 Armor\n+21 Stamina\nDurability 70 / 70\nRequires Engineering (375)\nRequiresGnomish Engineer\n[q2]Equip: Increases attack power by 100.\n[q2]Equip: Increases your critical strike rating by 28.\nSell Price: 3 83 21"},
    [23830] = {name = "Clopper's Equipment", additional_info = "Quest Item\nUnique\n[q]\"The equipment appears unharmed, if a bit slimy.\""},
    [23831] = {name = "Goblin Tonk Controller", additional_info = "[q2]Use: Take control of a Steam Tonk.\n50 ChargesSell Price: 50"},
    [23832] = {name = "Gnomish Tonk Controller", additional_info = "[q2]Use: Take control of a Steam Tonk.\n50 ChargesSell Price: 50"},
    [23833] = {name = "Crude Murloc Knife", additional_info = "Quest Item\n[q]\"A crudely knapped stone blade affixed to a long stick with sinew.\""},
    [23834] = {name = "Crude Murloc Idol", additional_info = "Quest Item\n[q]\"A roughly carved idol depicting no discernable figure.\""},
    [23835] = {name = "[q3]Gnomish Poultryizer", additional_info = "Binds when equipped\nTrinket\n+45 Stamina\nRequires Engineering (340)\nRequiresGnomish Engineer\n[q2]Use: Turns the target into a chicken for 15 sec.  Well, that is assuming the transmogrification polarity has not been reversed... (5 Min Cooldown)\nSell Price: 2 25"},
    [23836] = {name = "[q3]Goblin Rocket Launcher", additional_info = "Binds when equipped\nTrinket\n+45 Stamina\nRequires Engineering (350)\nRequiresGoblin Engineer\n[q2]Use: Fire a powerful rocket at the enemy that does 960 to 1440 damage and stuns them for 3 sec.  This thing has quite a kick though... (2 Min Cooldown)\nSell Price: 2 25"},
    [23837] = {name = "Weathered Treasure Map", additional_info = "Binds when picked up\nUnique\nThis Item Begins a Quest\nRequires Level 13\n[q]\"The parchment is yellowed, faded, and full of holes, but most of the writing is still visible.\""},
    [23838] = {name = "[q4]Foreman's Enchanted Helmet", additional_info = "Binds when picked up\nHead Cloth\n132 Armor\n+48 Stamina\n+30 Intellect\nDurability 60 / 60\nRequires Engineering (350)\nRequiresGoblin Engineer\n[q2]Equip: +10% Stun Resistance.\n[q2]Equip: Increases spell power by 36.\nSell Price: 2 94 54"},
    [23839] = {name = "[q4]Foreman's Reinforced Helmet", additional_info = "Binds when picked up\nHead Mail\n550 Armor\n+30 Agility\n+48 Stamina\nDurability 85 / 85\nRequires Engineering (350)\nRequiresGoblin Engineer\n[q2]Equip: Increases attack power by 62.\n[q2]Equip: Increases your chance to resist Stun and Disorient effects by 10%.\nSell Price: 4 43 45"},
    [23840] = {name = "Remote Mail Terminal", additional_info = "Requires Engineering (335)\n[q2]Use: Unfold the Remote Mail Terminal so that it can receive and send mail.  It only has enough power to last for 5 min.\nSell Price: 1"},
    [23841] = {name = "Gnomish Flame Turret", additional_info = "Requires Engineering (325)\n[q2]Use: Quickly constructs a gnomish flame turret at your feet that will nearly always attack nearby enemies. The turret falls apart after 45 sec. (1 Min Cooldown)\nSell Price: 30"},
    [23843] = {name = "Whorl of Air", additional_info = "Quest Item\nUnique\n[q]\"A swirl from Susurrus somehow retains its cohesion in your hand.\""},
    [23844] = {name = "[q2]Nolkai's Lantern", additional_info = "Binds when picked up\nHeld In Off-hand\n+3 Intellect\nSell Price: 6 66"},
    [23845] = {name = "Ravager Hide", additional_info = "Quest Item"},
    [23846] = {name = "Nolkai's Box", additional_info = "Binds when picked up\nUnique\n[q2]<Right Click to Open>"},
    [23847] = {name = "[q0]Nolkai's Band", additional_info = "[q]\"An inscription on the inside of the band reads: A token for my love to remember me by. May Elune watch over my dear Nolkai.\""},
    [23848] = {name = "Nethergarde Bitter", additional_info = "Requires Level 30\n[q2]Use: An extremely potent alcoholic beverage.\nSell Price: 5"},
    [23849] = {name = "Stillpine Grain", additional_info = "Quest Item"},
    [23850] = {name = "Gurf's Dignity", additional_info = "Binds when picked up\nUnique\nThis Item Begins a Quest\nRequires Level 7\n[q]\"A small patch of white fur belonging to Gurf of the Stillpine.\""},
    [23851] = {name = "Battered Journal", additional_info = "Quest Item\nUnique\n[q]\"The cover of this journal is well worn and its pages yellowed, but two sets of text are still visible within.\""},
    [23852] = {name = "[q2]Nolkai's Bag", additional_info = "Binds when picked up\n8 Slot Bag\n[q]\"Despite its long time buried in the earth, this bag seems nearly new.\"\nSell Price: 8 75"},
    [23853] = {name = "Letter to", additional_info = nil},
    [23854] = {name = "[q3]Shadoweave Cloth", additional_info = "Sell Price: 40"},
    [23855] = {name = "[q3]Spellfire Cloth", additional_info = "Sell Price: 40"},
    [23856] = {name = "[q0]Monster - Mace2H, Horde Black Spiked Badass Fire", additional_info = "Two-Hand Mace\n2 - 3 Damage Speed 2.90\n(0.86 damage per second)\nDurability 20 / 20\nSell Price: 3"},
    [23857] = {name = "Legacy of the Mountain King", additional_info = "Karazhan\nUnique\n[q2]Use: Break the seal of the book, granting you a chance to increase your armor and resistance to magic when struck in combat. (Proc chance: 3%)\n[q]\"The essence of this book is bound to Karazhan.\""},
    [23858] = {name = "Singed Page", additional_info = "[q]\"One page remains after breaking the seal on 'Legacy of the Mountain King.'\"\n[q2]<Right Click to Read>\nSell Price: 15"},
    [23859] = {name = "Nazzivus Monument Glyph", additional_info = "Quest Item\nUnique\n[q]\"Wicked looking characters accompany a series of humanoid figures as part of some kind of narrative.\""},
    [23860] = {name = "The Kurken's Hide", additional_info = "Quest Item\nUnique"},
    [23861] = {name = "Drawing Kit", additional_info = "Quest Item\nUnique\n[q2]Use: Create a rubbing from the Nazzivus satyr monument.\n[q]\"A simple portable drawing kit for making sketches or rubbings in the field.\""},
    [23862] = {name = "Redemption of the Fallen", additional_info = "Karazhan\nUnique\n[q2]Use: Break the seal on the book, granting your healing spells the chance to summon a ghostly ally. (Proc chance: 3%)\n[q]\"The essence of this book is bound to Karazhan.\""},
    [23863] = {name = "Corrupted Crystal", additional_info = "Quest Item\n[q]\"The crystal pulsates with an angry red light. It's hard to believe such a thing was once a part of the Exodar.\""},
    [23864] = {name = "Torment of the Worgen", additional_info = "Karazhan\nUnique\n[q2]Use: Break the seal on the book, granting you a chance to deal additional shadow damage on ranged or melee attacks.\n[q]\"The essence of this book is bound to Karazhan.\""},
    [23865] = {name = "Wrath of the Titans", additional_info = "Karazhan\nUnique\n[q2]Use: Break the seal of the book, granting your harmful spells a chance to deal additional damage. (Proc chance: 3%, 30s cooldown)\n[q]\"The essence of this book is bound to Karazhan.\""},
    [23866] = {name = "Singed Page", additional_info = "[q]\"One page remains after breaking the seal on 'Redemption of the Fallen.'\"\n[q2]<Right Click to Read>\nSell Price: 15"},
    [23867] = {name = "Singed Page", additional_info = "[q]\"One page remains after breaking the seal on the 'Wrath of the Titans.'\"\n[q2]<Right Click to Read>\nSell Price: 15"},
    [23868] = {name = "Singed Page", additional_info = "[q]\"One page remains after breaking the seal on 'Torment of the Worgen.'\"\n[q2]<Right Click to Read>\nSell Price: 15"},
    [23869] = {name = "Crystallized Bark", additional_info = "Quest Item\n[q]\"Pieces of red crystal have become embedded within the bark and appear to be replacing the wood.\""},
    [23870] = {name = "Red Crystal Pendant", additional_info = "Binds when picked up\nUnique\nThis Item Begins a Quest\nRequires Level 9\n[q]\"A piece of jewelry fashioned from a crystal shard and a rolled seaweed cord.\""},
    [23871] = {name = "Potion of Water Breathing", additional_info = "Binds when picked up\nUnique (3)\nRequires Level 8\n[q2]Use: Allows the Imbiber to breathe water for 30 min. (3 Sec Cooldown)"},
    [23872] = {name = "Blue Satchel", additional_info = "Binds when picked up\nUnique"},
    [23873] = {name = "Galaen's Amulet", additional_info = "Quest Item\nUnique\n[q]\"A small jeweled charm dangles from the end of a fine chain.\""},
    [23874] = {name = "Schematic: Elemental Seaforium Charge", additional_info = "Binds when picked up\nRequires Engineering (350)\nRequiresThe Consortium\n- Revered\n[q2]Use: Teaches you how to make an Elemental Seaforium Charge.\nSell Price: 2\nElemental Seaforium Charge\nRequires Engineering (350)\n[q2]Use: Blasts open all but the mightiest of locked doors and chests.\nSell Price: 60\nRequires Elemental Blasting Powder (2), Fel Iron Casing , Handful of Fel Iron Bolts"},
    [23875] = {name = "Crystal Mining Pick", additional_info = "Quest Item\nUnique\n[q2]Use: Mine a sample of the crystal from among the crash debris."},
    [23876] = {name = "Crystal Mining Pick", additional_info = "Quest Item\nUnique\n[q2]Use: Mine a sample shard from a crystal used by the blood elves."},
    [23877] = {name = "Crystal Mining Pick", additional_info = "Quest Item\nUnique\n[q2]Use: Mine a sample shard from a crystal in the Nazzivus settlement of Axxarien."},
    [23878] = {name = "Impact Site Crystal Sample", additional_info = "Unique\n[q]\"A chunk of crystal from Exodar crash debris.\""},
    [23879] = {name = "Altered Crystal Sample", additional_info = "Quest Item\nUnique\n[q]\"A shard of crystal that once formed part of the Exodar, but has been modified by blood elves.\""},
    [23880] = {name = "Axxarien Crystal Sample", additional_info = "Quest Item\nUnique\n[q]\"A sample chipped from the crystals found in satyr settlements.\""},
    [23881] = {name = "Gargolmar's Hand", additional_info = "Quest Item\nUnique"},
    [23882] = {name = "[q3]Schematic: Critter Enlarger", additional_info = "Binds when picked up\nRequires Engineering (325)\n[q2]Use: Teaches you how to make a Critter Enlarger.\nSell Price: 1 50\n[q2]Critter Enlarger\nRequires Engineering (325)\n[q2]Use: Enlarges a critter to twice its normal size. (15 Sec Cooldown)\n[q]\"The practical uses for this device are nearly limitless.\"\nSell Price: 1 50\nRequires Adamantite Frame , Handful of Fel Iron Bolts (2), Gold Power Core"},
    [23883] = {name = "[q3]Schematic: Healing Potion Injector", additional_info = "Requires Engineering (330)\n[q2]Use: Teaches you how to make a Healing Potion Injector.\nSell Price: 1 75\nHealing Potion Injector\nRequires Level 55\n[q2]Use: Restores 1500 to 2500 health. Increased effect for engineers! (1 Min Cooldown)\nSell Price: 50\nRequires Fel Iron Casing , Handful of Fel Iron Bolts , Knothide Leather (2), Super Healing Potion (20)"},
    [23884] = {name = "[q3]Schematic: Mana Potion Injector", additional_info = "Requires Engineering (345)\n[q2]Use: Teaches you how to make a Mana Potion Injector.\nSell Price: 2\nMana Potion Injector\nRequires Level 55\n[q2]Use: Restores 1800 to 3000 mana. Increased effect for engineers! (1 Min Cooldown)\nSell Price: 50\nRequires Fel Iron Casing , Handful of Fel Iron Bolts , Knothide Leather (2), Super Mana Potion (20)"},
    [23885] = {name = "[q3]Schematic: Remote Mail Terminal", additional_info = "Requires Engineering (335)\n[q2]Use: Teaches you how to make a Remote Mail Terminal.\nSell Price: 1 25\nRemote Mail Terminal\nRequires Engineering (335)\n[q2]Use: Unfold the Remote Mail Terminal so that it can receive and send mail.  It only has enough power to last for 5 min.\nSell Price: 1\nRequires Adamantite Frame , Handful of Fel Iron Bolts (2), Khorium Power Core , Fused Wiring"},
    [23886] = {name = "Omor's Hoof", additional_info = "Quest Item\nUnique"},
    [23887] = {name = "[q3]Schematic: Rocket Boots Xtreme", additional_info = "Binds when picked up\nRequires Engineering (355)\n[q2]Use: Teaches you how to make Rocket Boots Xtreme.\nSell Price: 1 50\n[q3]Rocket Boots Xtreme\nBinds when equipped\nFeet Leather\n196 Armor\nDurability 50 / 50\nRequires Engineering (330)\n[q2]Equip: Increases attack power by 80.\n[q2]Use: Engage the rocket boots to greatly increase your speed. (5 Min Cooldown)\nSell Price: 3 27 34\nRequires Heavy Knothide Leather (8), Khorium Power Core (2), Hardened Adamantite Tube (2), Felsteel Stabilizer (4)"},
    [23888] = {name = "Schematic: Zapthrottle Mote Extractor", additional_info = "Binds when picked up\nRequires Engineering (305)\n[q2]Use: Teaches you how to make a Zapthrottle Mote Extractor.\nSell Price: 60\nZapthrottle Mote Extractor\nUnique\nRequires Engineering (305)\n[q2]Use: Extracts gas from a nearby gas cloud.\n[q2]Shows the location of nearby gas clouds on the minimap while the mote extractor remains in your inventory.\nSell Price: 1 50\nRequires Fel Iron Casing (2), Handful of Fel Iron Bolts (2), Primal Life (4), Delicate Arcanite Converter"},
