    [24000] = {name = "Formula: Enchant Bracer - Superior Healing", additional_info = "Binds when picked up\nRequires Enchanting (325)\nRequiresThrallmar\n- Friendly\n[q2]Use: Teaches you how to permanently enchant bracers to increase spell power by 15. Requires a level 35 or higher item.\n[q2]Permanently enchant bracers to increase spell power by 15. Requires a level 35 or higher item.\nSell Price: 1 50"},
    [24001] = {name = "Recipe: Elixir of Major Agility", additional_info = "Binds when picked up\nRequires Alchemy (330)\nRequiresThrallmar\n- Honored\n[q2]Use: Teaches you how to make an Elixir of Major Agility.\nSell Price: 1 25\nElixir of Major Agility\nRequires Level 55\n[q2]Use: Increases your Agility by 30 and your critical strike rating by 12 for 1 hour. Battle Elixir. (3 Sec Cooldown)\nSell Price: 40\nRequires Terocone , Felweed (2), Imbued Vial"},
    [24002] = {name = "Plans: Felsteel Shield Spike", additional_info = "Binds when picked up\nRequires Blacksmithing (360)\nRequiresThrallmar\n- Exalted\n[q2]Use: Teaches you how to make a Felsteel Shield Spike.\nSell Price: 1 50\n[q2]Felsteel Shield Spike\n[q2]Use: Attaches a Felsteel Spike to your shield that deals 26-38 damage every time you block with it.\nSell Price: 1 20\nRequires Felsteel Bar (4), Primal Fire (4), Primal Earth (4)"},
    [24003] = {name = "Formula: Enchant Chest - Exceptional Stats", additional_info = "Binds when picked up\nRequires Enchanting (345)\nRequiresThrallmar\n- Revered\n[q2]Use: Teaches you how to permanently enchant chest armor to increase all stats by 6. Requires a level 35 or higher item.\n[q2]Permanently enchant chest armor to increase all stats by 6. Requires a level 35 or higher item.\nSell Price: 1 50"},
