    [24101] = {name = "[q3]Book of Ferocious Bite V", additional_info = "Classes: Druid\nRequires Level 60\n[q2]Use: Teaches Ferocious Bite (Rank 5).\n[q2]Finishing move that causes damage per combo point and converts each extra point of energy (up to a maximum of 30 extra energy) into (2.0999999 + Attack power / 410) additional damage. Damage is increased by your attack power.\n 1 point : (52 + 147 * 1 + 0.07 * Attack power)-(112 + 147 * 1 + 0.07 * Attack power) damage\n 2 points: (52 + 147 * 2 + 0.14 * Attack power)-(112 + 147 * 2 + 0.14 * Attack power) damage\n 3 points: (52 + 147 * 3 + 0.21 * Attack power)-(112 + 147 * 3 + 0.21 * Attack power) damage\n 4 points: (52 + 147 * 4 + 0.28 * Attack power)-(112 + 147 * 4 + 0.28 * Attack power) damage\n 5 points: (52 + 147 * 5 + 0.35 * Attack power)-(112 + 147 * 5 + 0.35 * Attack power) damage\nSell Price: 10"},
    [24102] = {name = "[q3]Manual of Eviscerate IX", additional_info = "Classes: Rogue\nRequires Level 60\n[q2]Use: Teaches Eviscerate (Rank 9).\n[q2]Finishing move that causes damage per combo point:\n 1 point : [54 + ((170) + Attack power * 0.03) * ( 1 ) ]-[162 + ((170) + Attack power * 0.07) * ( 1 ) ] damage\n 2 points: [54 + ((340) + Attack power * 0.06) * ( 1 ) ]-[162 + ((340) + Attack power * 0.14) * ( 1 ) ] damage\n 3 points: [54 + ((510) + Attack power * 0.09) * ( 1 ) ]-[162 + ((510) + Attack power * 0.21) * ( 1 ) ] damage\n 4 points: [54 + ((680) + Attack power * 0.12) * ( 1 ) ]-[162 + ((680) + Attack power * 0.28) * ( 1 ) ] damage\n 5 points: [54 + ((850) + Attack power * 0.15) * ( 1 ) ]-[162 + ((850) + Attack power * 0.35) * ( 1 ) ] damage\nSell Price: 10"},
