    [30316] = {name = "[q5]Devastation", additional_info = "Tempest Keep\nUnique\nDuration: 15 min (real time)Two-Hand Axe\n496 - 744 Damage Speed 3.90\n(158.97 damage per second)\n+75 Stamina\nDurability 145 / 145\nRequires Level 70\n[q2]Equip: Improves critical strike rating by 50.\n[q2]Equip: Increases attack power by 150.\n[q2]Chance on hit: Increases your movement speed by 50%, and your melee attack speed by 20% for 30 sec."},
