    [32757] = {name = "[q4]Blessed Medallion of Karabor", additional_info = "Binds when picked up\nUnique\nNeck\n+49 Stamina\n+40 Shadow Resistance\n[q2]Use: Teleports the bearer to the footsteps of Illidan's fortress. (15 Min Cooldown)\n[q]\"Once worn by a cleric of Karabor, this item allows the wearer entry into the Black Temple.\""},
    [32758] = {name = "Brute Cologne", additional_info = "[q2]Use: Splash it all over to unleash the sophisticated ogre inside. Creatures of all kinds will be certain to notice you from afar.\n\n Only works in Blade's Edge Mountains.\n[q]\"A delicate fragrance for the discerning ogre.\"\nSell Price: 25"},
