    [32764] = {name = "Flaskataur's Celestial Brew", additional_info = "Requires Level 65\n[q2]Use: Increases maximum health by 500 and defense rating by 10 for 1 hour. Counts as both a Battle and Guardian elixir. This effect persists through death. (3 Sec Cooldown)\n[q]\"Flasky essence captured from the mythical beast!\"\nSell Price: 2"},
    [32765] = {name = "Flaskataur's Tears", additional_info = "Requires Level 65\n[q2]Use: Increases attack power by 120 for 1 hour. Counts as both a Battle and Guardian elixir. This effect persists through death. (3 Sec Cooldown)\n[q]\"The distilled tears of the elusive Flaskataur.\"\nSell Price: 2"},
    [32766] = {name = "Flaskataur's Flask of Flaskocity", additional_info = "Requires Level 65\n[q2]Use: Increases mana regeneration by 31 mana per 5 seconds for 1 hour. Counts as both a Battle and Guardian elixir. This effect persists through death. (3 Sec Cooldown)\n[q]\"Bears the mark of Flaskataur.\"\nSell Price: 2"},
    [32767] = {name = "Flaskataur's Flask of Pretty Good Power", additional_info = "Requires Level 50\n[q2]Use: Increases spell power by 70 for 1 hour. Counts as both a Battle and Guardian elixir. This effect persists through death. (3 Sec Cooldown)\n[q]\"It's not supreme but it's not bad either.\"\nSell Price: 50"},
