    [33827] = {name = "The Warlord's Treatise", additional_info = "Quest Item\nUnique\n[q]\"Written in the water-proofed alien script of the naga, this volume is thousands of pages long.\""},
    [33828] = {name = "[q4]Tome of Diabolic Remedy", additional_info = "Binds when picked up\nUnique\nTrinket\nRequires Level 70\n[q2]Equip: Restores 23 mana per 5 sec.\n[q2]Use: Increases spell power by 211 for 20 sec. (2 Min Cooldown)\nSell Price: 9 11 60"},
    [33829] = {name = "[q4]Hex Shrunken Head", additional_info = "Binds when picked up\nUnique\nTrinket\nRequires Level 70\n[q2]Equip: Increases spell power by 53.\n[q2]Use: Increases spell power by 211 for 20 sec. (2 Min Cooldown)\nSell Price: 9 11 60"},
    [33830] = {name = "[q4]Ancient Aqir Artifact", additional_info = "Binds when picked up\nUnique\nTrinket\nRequires Level 70\n[q2]Equip: Increases your parry rating by 45.\n[q2]Use: Increases armor by 2500 for 20 sec. (2 Min Cooldown)\nSell Price: 9 11 60"},
    [33831] = {name = "[q4]Berserker's Call", additional_info = "Binds when picked up\nUnique\nTrinket\nRequires Level 70\n[q2]Equip: Increases attack power by 90.\n[q2]Use: Increases attack power by 360 for 20 sec. (2 Min Cooldown)\nSell Price: 9 11 60"},
    [33832] = {name = "[q4]Battlemaster's Determination", additional_info = "Binds when picked up\nTrinket\nRequires Level 70\n[q2]Equip: Increases attack power by 80.\n[q2]Use: Increases maximum health by 1750 for 15 sec. Shares cooldown with other Battlemaster's trinkets. (3 Min Cooldown)"},
    [33833] = {name = "Nazan's Riding Crop", additional_info = "Quest Item\nUnique\n[q]\"This certainly looks as if it would hurt.\""},
    [33834] = {name = "The Headfeathers of Ikiss", additional_info = "Quest Item\nUnique\n[q]\"The plumes are a display of beautiful autumnal hues.\""},
    [33835] = {name = "Shaffar's Wondrous Amulet", additional_info = "Quest Item\nUnique\n[q]\"This is the source of Nexus-Prince Shaffar's magic. Too bad that you can't figure out how to use it.\""},
    [33836] = {name = "The Exarch's Soul Gem", additional_info = "Quest Item\nUnique\n[q]\"It's hard to believe that this bauble holds the spirits of many victims. Nevertheless, you can sense them in turmoil within.\""},
    [33837] = {name = "Cooking Pot", additional_info = "Quest Item\nRequires Cooking (275)\n[q2]Use: Cook up some Kaliri Stew using 3 Warp Burgers and 1 Giant Kaliri Wing."},
    [33838] = {name = "Giant Kaliri Wing", additional_info = "Quest Item"},
    [33839] = {name = "Kaliri Stew", additional_info = "Quest Item\n[q]\"Looks like revenge is on the menu tonight! Kaliri never tasted so good.\""},
    [33840] = {name = "Murmur's Whisper", additional_info = "Quest Item\nUnique\n[q]\"The professor was right, Murmur's 'whisper' does have a physical manifestation!\""},
    [33841] = {name = "[q4]Vengeful Gladiator's Idol of Tenacity", additional_info = "Binds when picked up\nRelic Idol\nClasses: Druid\nRequires Level 70\n[q2]Equip: Increases the spell power of the final healing value of your Lifebloom by 116."},
    [33842] = {name = "[q4]Vengeful Gladiator's Libram of Justice", additional_info = "Binds when picked up\nRelic Libram\nClasses: Paladin\nRequires Level 70\n[q2]Equip: Causes your Flash of Light to increase the target's Resilience rating by 34 for 6 sec."},
    [33843] = {name = "[q4]Vengeful Gladiator's Totem of the Third Wind", additional_info = "Binds when picked up\nRelic Totem\nClasses: Shaman\nRequires Level 70\n[q2]Equip: Causes your Lesser Healing Wave to increase the target's Resilience rating by 34 for 6 sec.\n[q]\"Counts as an Air, Earth, Fire, and Water totem.\""},
    [33844] = {name = "Barrel of Fish", additional_info = "Binds when picked up\n[q]\"A warning label reads: Do Not Shoot.\"\n[q2]<Right Click to Open>\nSell Price: 87"},
    [33846] = {name = "[q0]Ruined Fishing Net", additional_info = "Sell Price: 4 63"},
    [33847] = {name = "Epoch Hunter's Head", additional_info = "Quest Item\nUnique\n[q]\"It'll look fine mounted just so long as the wind trader's customer has plenty of wall space.\""},
    [33848] = {name = "Demon Broiled Surprise", additional_info = "Quest Item\n[q]\"Smells delicious!\""},
    [33849] = {name = "Mana Berry", additional_info = "Quest Item"},
    [33850] = {name = "Spiritual Soup", additional_info = "Quest Item\n[q]\"It's not made of chicken, but it's definitely good for the soul.\""},
    [33851] = {name = "Cooking Pot", additional_info = "Quest Item\nRequires Cooking (275)\n[q2]Use: Cook up some Spiritual Soup using 4 Roasted Clefthoof.\n[q]\"Can only be used at the Ancestral Grounds in Nagrand.\""},
    [33852] = {name = "Cooking Pot", additional_info = "Quest Item\nRequires Cooking (275)\n[q2]Use: Cook up some Demon Broiled Surprise using 2 Mok'Nathal Shortribs and 1 Crunchy Serpent.\n[q]\"Requires the smoldering corpse of an Abyssal Flamebringer.\""},
    [33853] = {name = "[q4]Vindicator's Band of Dominance", additional_info = "Binds when picked up\nUnique\nFinger\n+31 Stamina\n+15 Intellect\nRequires Level 70\n[q2]Equip: Improves your resilience rating by 22.\n[q2]Equip: Increases spell power by 33.\n[q2]Equip: Increases your spell penetration by 14."},
    [33854] = {name = "[q0]Unidentified Eye", additional_info = "[q]\"Maybe it belonged to an animal, and maybe it didn't.\"\nSell Price: 5 63"},
    [33855] = {name = "[q0]Tarnished Silver Ring", additional_info = "Finger\n[q]\"This ring has seen better days.\"\nSell Price: 37 50"},
    [33856] = {name = "[q0]List of Goods", additional_info = "[q]\"Blood and water stains have made the list unreadable.\"\nSell Price: 33"},
    [33857] = {name = "Crate of Meat", additional_info = "Binds when picked up\n[q]\"Mostly meat and whatever else was sitting around.\"\n[q2]<Right Click to Open>\nSell Price: 1 13"},
    [33858] = {name = "Aeonus's Hourglass", additional_info = "Quest Item\nUnique\n[q]\"The sands are falling upward!\""},
    [33859] = {name = "Warp Splinter Clipping", additional_info = "Quest Item\nUnique\n[q]\"Hard to believe that the druids think they can regrow such a massive ancient from such a small twig.\""},
    [33860] = {name = "Pathaleon's Projector", additional_info = "Quest Item\nUnique\n[q]\"So this is what he used to appear all over the place!\""},
    [33861] = {name = "The Scroll of Skyriss", additional_info = "Quest Item\nUnique\n[q]\"Indeed, the language written upon the scroll is illegible. In fact, it hurts your brain to even look upon it!\""},
    [33862] = {name = "Brewfest Regalia", additional_info = "Binds when picked up\nUnique\nChest\n[q]Brewfest Garb (0/3)\n[q0]Brewfest Regalia\nBrewfest Dress\nBrewfest Boots\nBrewfest Slippers\nPurple Brewfest Hat\nGreen Brewfest Hat\nBrown Brewfest Hat\nBlue Brewfest Hat\n[q0](3) Set : Full Brewfest Garb"},
