    [33865] = {name = "[q2]Amani Hex Stick", additional_info = "Zul'Aman\n[q2]Use: Removes the Amani hex from a forest frog in Zul'Aman.\n[q]\"It be yer trusty anti-hexxor', mon!\"\nSell Price: 4"},
    [33866] = {name = "Stormchops", additional_info = "Requires Level 55\n[q2]Use: Charges you with energy, causing lightning to occasionally zap nearby enemies for the next 30 min. (10s cooldown)\nSell Price: 5 50"},
    [33867] = {name = "Broiled Bloodfin", additional_info = "Requires Level 55\n[q2]Use: Restores 4320 health over 30 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed and gain 8 resistance to all schools of magic for 30 min.\nSell Price: 8"},
