    [34470] = {name = "[q4]Timbal's Focusing Crystal", additional_info = "Binds when picked up\nUnique\nTrinket\nRequires Level 70\n[q2]Equip: Each time one of your spells deals periodic damage, there is a chance 285 to 475 additional damage will be dealt. (Proc chance: 10%, 15s cooldown)\n[q2]Equip: Increases spell power by 44.\nSell Price: 7 20 39"},
    [34471] = {name = "[q4]Vial of the Sunwell", additional_info = "Binds when picked up\nUnique\nTrinket\nRequires Level 70\n[q2]Equip: Collects 100 Holy Energy from healing spells you cast. Cannot collect more than 2000 Holy Energy.\n[q2]Use: Release all accumulated Holy Energy to instantly heal current friendly target by the amount of Holy Energy accumulated. (2 Min Cooldown)\n[q2]Equip: Restores 19 mana per 5 sec.\nSell Price: 7 20 39"},
    [34472] = {name = "[q4]Shard of Contempt", additional_info = "Binds when picked up\nUnique\nTrinket\nRequires Level 70\n[q2]Equip: Increases your expertise rating by 44.\n[q2]Equip: Chance on hit to increase your attack power by 230 for 20 sec. (Proc chance: 10%, 45s cooldown)\nSell Price: 7 20 39"},
    [34473] = {name = "[q4]Commendation of Kael'thas", additional_info = "Binds when picked up\nUnique\nTrinket\n+57 Stamina\nRequires Level 70\n[q2]Equip: Melee attacks which reduce you below 35% health cause you to gain 152 dodge rating for 10 sec. Cannot occur more than once every 30 sec. (30s cooldown)\nSell Price: 7 20 39"},
    [34474] = {name = "Strange Engine Part", additional_info = "Binds when picked up\n[q]\"It reads 'Capissen 38' on the bottom.\""},
