    [34483] = {name = "Orb of Murloc Control", additional_info = "Quest Item\nUnique (10)\n[q2]Use: Throw and break near Greengill slaves in order to free them from their mind control. Affected murlocs will turn on their former masters.\n[q]\"An arcane energy swirls within this fragile container.\""},
    [34484] = {name = "[q2]Old Ironjaw", additional_info = "Binds when picked up\nHeld In Off-hand\n+5 Stamina\n[q]\"The legendary uncatchable fish of Ironforge. Just holding this scaly old monster makes you feel tough.\"\nSell Price: 25"},
    [34485] = {name = "[q0]Lightbringer Girdle", additional_info = "Binds when picked up\nWaist Plate\n1081 Armor\n+44 Strength\n+24 Stamina\n\n[q0]Red Socket\n[q0]Socket Bonus: +2 Critical Strike Rating\n\nDurability 55 / 55Classes: Paladin\nRequires Level 70\n[q2]Equip: Improves critical strike rating by 42.\n[q2]Equip: Improves haste rating by 29.\n[q2]Equip: Increases your expertise rating by 25.\n\n[q]Lightbringer Battlegear (0/8)\n[q0]Lightbringer Breastplate\nLightbringer Gauntlets\nLightbringer Greaves\nLightbringer Shoulderbraces\nLightbringer War-Helm\nLightbringer Boots\nLightbringer Bands\nLightbringer Girdle\n[q0](2) Set : Your melee attacks have a chance to grant you 50 mana. (Proc chance: 20%)\n(4) Set : Increases the damage dealt by your Hammer of Wrath ability by 10%."},
    [34486] = {name = "[q2]Old Crafty", additional_info = "Binds when picked up\nHeld In Off-hand\n+5 Stamina\n[q]\"Said to be the craftiest fish in Orgrimmar, it appears he was outsmarted at last.\"\nSell Price: 25"},
    [34487] = {name = "[q4]Lightbringer Belt", additional_info = "Binds when picked up\nWaist Plate\n1081 Armor\n+21 Stamina\n+29 Intellect\n\n[q0]Red Socket\n[q0]Socket Bonus: +1 Mana per 5 sec.\n\nDurability 55 / 55Classes: Paladin\nRequires Level 70\n[q2]Equip: Improves critical strike rating by 17.\n[q2]Equip: Improves haste rating by 24.\n[q2]Equip: Increases spell power by 50.\n[q2]Equip: Restores 15 mana per 5 sec.\n\n[q]Lightbringer Raiment (0/8)\n[q0]Lightbringer Chestpiece\nLightbringer Gloves\nLightbringer Greathelm\nLightbringer Leggings\nLightbringer Pauldrons\nLightbringer Bracers\nLightbringer Belt\nLightbringer Treads\n[q0](2) Set : Increases the spell power of your Flash of Light ability by 5%.\n(4) Set : Increases the critical strike chance of your Holy Light ability by 5%."},
    [34488] = {name = "[q4]Lightbringer Waistguard", additional_info = "Binds when picked up\nWaist Plate\n1081 Armor\n+30 Strength\n+64 Stamina\n\n[q0]Blue Socket\n[q0]Socket Bonus: +2 Dodge Rating\n\nDurability 55 / 55Classes: Paladin\nRequires Level 70\n[q2]Equip: Increases your shield block rating by 20.\n[q2]Equip: Increases defense rating by 28.\n[q2]Equip: Increases your dodge rating by 28.\n\n[q]Lightbringer Armor (0/8)\n[q0]Lightbringer Chestguard\nLightbringer Faceguard\nLightbringer Handguards\nLightbringer Legguards\nLightbringer Shoulderguards\nLightbringer Waistguard\nLightbringer Wristguards\nLightbringer Stompers\n[q0](2) Set : Increases the mana gained from your Spiritual Attunement ability by 10%.\n(4) Set : Increases the damage dealt by your Consecration ability by 10%."},
