    [34530] = {name = "[q4]Vengeful Gladiator's Rifle", additional_info = "Binds when picked up\nRanged Gun\n223 - 336 Damage Speed 3.00\n(93.17 damage per second)\n+24 Stamina\nDurability 90 / 90\nRequires Level 70\n[q2]Equip: Improves critical strike rating by 16.\n[q2]Equip: Improves your resilience rating by 13.\n[q2]Equip: Increases ranged attack power by 34."},
