    [40772] = {name = "Gnomish Army Knife", additional_info = "[q2]Use: A grand master engineer can overload the knife's battery to attempt to shock a dead player back to life. Cannot be used in combat. (30 Min Cooldown)\n\"Includes Gyromatic Micro-Adjuster, Arclight Spanner, Flint and Tinder, Blacksmithing Hammer, Mining Pick, and a Skinning Knife.\"Sell Price: 22 56"},
    [40773] = {name = "Master Firestone", additional_info = "Binds when picked up\nUnique\n[q2]Use: While applied to target weapon it increases damage dealt by direct spells by 1% and spell critical strike rating by 35. Lasts for 1 hour.\n5 Charges"},
    [40775] = {name = "[q4]Winged Steed of the Ebon Blade", additional_info = "Binds when picked up\nUnique\nMountClasses: Death Knight\nRequires Level 60\nRequires Riding (225)\n[q2]Use: Speed scales to riding skill.\nSummons and dismisses your Winged Steed of the Ebon Blade. This mount can only be summoned in Outland and Northrend. This mount changes speed depending on your Riding skill."},
    [40776] = {name = "Personal Electromagnetic Pulse Generator", additional_info = "Requires Engineering (375)\n[q2]Use: Permanently attaches a high-powered device to your belt, allowing you to confuse nearby mechanicals. Only a skilled engineer can activate the modified belt.\n\n Can only be attached to your own belt, and doing so causes the belt to become soulbound.\nSell Price: 12 50"},
