    [41090] = {name = "Monster - Zul'Aman - Staff, 2H, Drakuru Prophet", additional_info = "Two-Hand Staff\n110 - 165 Damage Speed 2.70\n(50.93 damage per second)\nDurability 85 / 85\nSell Price: 3 37 96"},
    [41091] = {name = "Hand-Mounted Pyro Rocket", additional_info = "Requires Engineering (375)\n[q2]Use: Permanently attaches a hand-mounted pyro rocket launcher to your gloves, allowing a skilled engineer to deal 1654 to 2020 Fire damage to an enemy at long range. The rocket can only be fired once every 45 sec.\n\n Can only be used on the engineer's gloves, and doing so will cause them to become soulbound.\nSell Price: 12 50"},
    [41092] = {name = "Glyph of Judgement", additional_info = "[q9]Major Glyph\nClasses: Paladin\nRequires Level 15\n[q2]Use: Permanently teaches you this glyph.\n\nYour Judgements deal 10% more damage.\nSell Price: 1"},
    [41093] = {name = "Hyperspeed Accelerators", additional_info = "Requires Engineering (375)\n[q2]Use: Increases your haste rating by 340 for 12 sec. (1 Min Cooldown)\nSell Price: 12 50"},
    [41094] = {name = "Glyph of Seal of Command", additional_info = "[q9]Major Glyph\nClasses: Paladin\nRequires Level 20\n[q2]Use: Permanently teaches you this glyph.\n\nYou gain 8% of your base mana each time you use a Judgement with Seal of Command active.\nSell Price: 1"},
    [41095] = {name = "Glyph of Hammer of Justice", additional_info = "[q9]Major Glyph\nClasses: Paladin\nRequires Level 15\n[q2]Use: Permanently teaches you this glyph.\n\nIncreases your Hammer of Justice range by 5 yards.\nSell Price: 1"},
    [41096] = {name = "Glyph of Spiritual Attunement", additional_info = "[q9]Major Glyph\nClasses: Paladin\nRequires Level 18\n[q2]Use: Permanently teaches you this glyph.\n\nIncreases the amount of mana gained from your Spiritual Attunement spell by an additional 2%.\nSell Price: 1"},
    [41097] = {name = "Glyph of Hammer of Wrath", additional_info = "[q9]Major Glyph\nClasses: Paladin\nRequires Level 44\n[q2]Use: Permanently teaches you this glyph.\n\nReduces the mana cost of Hammer of Wrath by 100%.\nSell Price: 1"},
    [41098] = {name = "Glyph of Crusader Strike", additional_info = "[q9]Major Glyph\nClasses: Paladin\nRequires Level 20\n[q2]Use: Permanently teaches you this glyph.\n\nReduces the mana cost of your Crusader Strike ability by 20%.\nSell Price: 1"},
    [41099] = {name = "Glyph of Consecration", additional_info = "[q9]Major Glyph\nClasses: Paladin\nRequires Level 20\n[q2]Use: Permanently teaches you this glyph.\n\nIncreases the duration and cooldown of Consecration by 2 sec.\nSell Price: 1"},
    [41100] = {name = "Glyph of Righteous Defense", additional_info = "[q9]Major Glyph\nClasses: Paladin\nRequires Level 15\n[q2]Use: Permanently teaches you this glyph.\n\nIncreases the chance for your Righteous Defense and Hand of Reckoning abilities to work successfully by 8% on each target.\nSell Price: 1"},
    [41101] = {name = "Glyph of Avenger's Shield", additional_info = "[q9]Major Glyph\nClasses: Paladin\nRequires Level 50\n[q2]Use: Permanently teaches you this glyph.\n\nYour Avenger's Shield hits 2 fewer targets, but for 100% more damage.\nSell Price: 1"},
    [41102] = {name = "Glyph of Turn Evil", additional_info = "[q9]Major Glyph\nClasses: Paladin\nRequires Level 24\n[q2]Use: Permanently teaches you this glyph.\n\nReduces the casting time of your Turn Evil spell by 100%, but increases the cooldown by 8 sec.\nSell Price: 1"},
    [41103] = {name = "Glyph of Exorcism", additional_info = "[q9]Major Glyph\nClasses: Paladin\nRequires Level 20\n[q2]Use: Permanently teaches you this glyph.\n\nIncreases damage done by Exorcism by 20%.\nSell Price: 1"},
    [41104] = {name = "Glyph of Cleansing", additional_info = "[q9]Major Glyph\nClasses: Paladin\nRequires Level 35\n[q2]Use: Permanently teaches you this glyph.\n\nReduces the mana cost of your Cleanse and Purify spells by 20%.\nSell Price: 1"},
    [41105] = {name = "Glyph of Flash of Light", additional_info = "[q9]Major Glyph\nClasses: Paladin\nRequires Level 20\n[q2]Use: Permanently teaches you this glyph.\n\nYour Flash of Light has an additional 5% critical strike chance.\nSell Price: 1"},
    [41106] = {name = "Glyph of Holy Light", additional_info = "Classes: Paladin\nRequires Level 15\n[q2]Use: Your Holy Light grants 10% of its heal amount to up to 5 friendly targets within 8 yards of the initial target.\nSell Price: 1"},
    [41107] = {name = "Glyph of Avenging Wrath", additional_info = "[q9]Major Glyph\nClasses: Paladin\nRequires Level 70\n[q2]Use: Permanently teaches you this glyph.\n\nReduces the cooldown of your Hammer of Wrath spell by 50% while Avenging Wrath is active.\nSell Price: 1"},
    [41108] = {name = "Glyph of Divinity", additional_info = "[q9]Major Glyph\nClasses: Paladin\nRequires Level 15\n[q2]Use: Permanently teaches you this glyph.\n\nYour Lay on Hands grants twice as much mana as normal and also grants you as much mana as it grants your target.\nSell Price: 1"},
    [41109] = {name = "Glyph of Seal of Wisdom", additional_info = "[q9]Major Glyph\nClasses: Paladin\nRequires Level 38\n[q2]Use: Permanently teaches you this glyph.\n\nWhile Seal of Wisdom is active, the cost of your healing spells is reduced by 5%.\nSell Price: 1"},
    [41110] = {name = "Glyph of Seal of Light", additional_info = "[q9]Major Glyph\nClasses: Paladin\nRequires Level 30\n[q2]Use: Permanently teaches you this glyph.\n\nWhile Seal of Light is active, the effect of your healing spells is increased by 5%.\nSell Price: 1"},
    [41111] = {name = "Flexweave Underlay", additional_info = "Requires Engineering (375)\nUse: Permanently attaches a flexweave underlay to a cloak, increasing Agility by 23 and allowing you to turn the cloak into a parachute to fall slowly for 30 sec.\n\n The cloak can only be used once a minute and requires an Engineering skill of at least 350.Sell Price: 12 50"},
    [41112] = {name = "[q3]Mechanized Snow Goggles", additional_info = "Binds when equipped\nHead Cloth\n225 Armor\n[q2]<Random enchantment>\nDurability 50 / 50\nRequires Engineering (400)\n[q2]Equip: Protected from the cold. Your Frost resistance is increased by 20.\nSell Price: 4 13 20"},
    [41113] = {name = "[q3]Saronite Bulwark", additional_info = "Binds when equipped\nOff Hand Shield\n6703 Armor\n187 Block\n+25 Strength\n+66 Stamina\nDurability 100 / 100\nRequires Level 77\n[q2]Equip: Increases defense rating by 31.\nSell Price: 8 48 25"},
