    [41118] = {name = "Nitro Boosts", additional_info = "Requires Engineering (375)\nUse: Permanently attaches overpowered nitro boosts to a pair of boots, increasing your critical strike rating by 24 and allowing you to greatly increase run speed for 5 sec.\n\n The nitro boosts can only be activated every 3 minutes and require an Engineering skill of at least 400.Sell Price: 12 50"},
    [41119] = {name = "Saronite Bomb", additional_info = "Requires Engineering (350)\n[q2]Use: Inflicts 1150 to 1500 Fire damage to targets in a 10 yard radius. This explosive is powerful enough to cause moderate siege damage. (1 Min Cooldown)\nSell Price: 2 50"},
    [41120] = {name = "[q2]Plans: Reinforced Cobalt Legplates", additional_info = "Binds when picked up\nRequires Blacksmithing (375)\n[q2]Use: Teaches you how to make Reinforced Cobalt Legplates\nSell Price: 6\n[q2]Reinforced Cobalt Legplates\nBinds when equipped\nLegs Plate\n1321 Armor\n+48 Strength\n+63 Stamina\nDurability 85 / 85\nRequires Level 76\n[q2]Equip: Improves critical strike rating by 31.\n[q2]Equip: Improves your resilience rating by 41.\nSell Price: 7 30 80\nRequires Cobalt Bar (8), Crystallized Water (2)"},
    [41121] = {name = "[q3]Gnomish Lightning Generator", additional_info = "Binds when picked up\nTrinket\nRequires Engineering (425)\n[q2]Equip: Improves critical strike rating by 84.\n[q2]Use: Generates a bolt of lightning to strike an enemy for 1530 to 1870 Nature damage. This entire device is made of metal.... (1 Min Cooldown)\n[q]\"It's safe!\"\nSell Price: 8 5 7"},
    [41122] = {name = "[q2]Plans: Reinforced Cobalt Chestpiece", additional_info = "Binds when picked up\nRequires Blacksmithing (375)\n[q2]Use: Teaches you how to make a Reinforced Cobalt Chestpiece\nSell Price: 6\n[q2]Reinforced Cobalt Chestpiece\nBinds when equipped\nChest Plate\n1545 Armor\n+47 Strength\n+64 Stamina\nDurability 115 / 115\nRequires Level 77\n[q2]Equip: Improves critical strike rating by 38.\n[q2]Equip: Improves your resilience rating by 43.\nSell Price: 7 49 92\nRequires Cobalt Bar (8), Crystallized Water (2)"},
