    [42984] = {name = "[q7]Preened Ironfeather Shoulders", additional_info = "Binds to account\nShoulder Leather\n395 Armor\n+38 Stamina\n+38 Intellect\n+51 Spirit\nRequires level 1 to 80 ( 80)\n[q2]Equip: Increases spell power by 59.\n[q2]Equip: Experience gained from killing monsters and completing quests increased by 10%."},
    [42985] = {name = "[q7]Tattered Dreadmist Mantle", additional_info = "Binds to account\nShoulder Cloth\n210 Armor\n+38 Stamina\n+38 Intellect\n+51 Spirit\nRequires level 1 to 80 ( 80)\n[q2]Equip: Increases spell power by 59.\n[q2]Equip: Experience gained from killing monsters and completing quests increased by 10%."},
    [42986] = {name = "The RP-GG", additional_info = "Wintergrasp\nUnique (5)\n[q2]Use: Fires a heat seeking missile that attempts to track enemy tanks.\n[q2]Rocket-Propelled Goblin Grenade launchers will be dropped on death.\n[q]\"For Military Use Only\""},
    [42987] = {name = "[q4]Darkmoon Card: Greatness", additional_info = "Binds when equipped\nUnique-Equipped\nTrinket\n+90 Strength\nRequires Level 80\n[q2]Equip: When you heal or deal damage you have a chance to gain Greatness, increasing your Strength, Agility, Intellect, or Spirit by 300 for 15 sec. Your highest stat is always chosen. (Proc chance: 35%, 45s cooldown)\nSell Price: 10 73 43"},
    [42988] = {name = "[q4]Darkmoon Card: Illusion", additional_info = "Binds when equipped\nUnique-Equipped\nTrinket\nRequires Level 80\n[q2]Equip: Increases spell power by 100.\n[q2]Use: Absorbs 1500 damage for 6 sec. When the shield is removed by any means, you regain 1500 mana. (5 Min Cooldown)\nSell Price: 10 73 43"},
    [42989] = {name = "[q4]Darkmoon Card: Berserker!", additional_info = "Binds when equipped\nUnique-Equipped\nTrinket\nRequires Level 80\n[q2]Equip: Improves your resilience rating by 100.\n[q2]Equip: You have a chance to gain Berserker when you deal or take damage in combat, increasing your critical strike rating by 35 for 12 sec. Effect stacks up to 3 times. (Proc chance: 50%)\nSell Price: 10 73 43"},
    [42990] = {name = "[q4]Darkmoon Card: Death", additional_info = "Binds when equipped\nUnique-Equipped\nTrinket\nRequires Level 80\n[q2]Equip: Improves critical strike rating by 85.\n[q2]Equip: Each time you deal damage, you have a chance to do an additional 1750 to 2250 Shadow damage. (Proc chance: 15%, 45s cooldown)\nSell Price: 10 73 43"},
    [42991] = {name = "[q7]Swift Hand of Justice", additional_info = "Binds to account\nTrinket\nRequires level 1 to 80 ( 80)\n[q2]Equip: Improves haste rating by 64.\n[q2]Equip: Heals you for 2% of your maximum health whenever you kill a target that yields experience or honor."},
