    [43590] = {name = "[q4]Polar Vest", additional_info = "Binds when equipped\nChest Leather\n578 Armor\n+169 Stamina\n+115 Frost Resistance\n\n[q0]Red Socket\n[q0]Yellow Socket\n[q0]Blue Socket\n[q0]Socket Bonus: +12 Stamina\n\nDurability 120 / 120\nRequires Level 80\nSell Price: 9 92 60"},
    [43591] = {name = "[q4]Polar Cord", additional_info = "Binds when equipped\nWaist Leather\n325 Armor\n+129 Stamina\n+86 Frost Resistance\n\n[q0]Red Socket\n[q0]Yellow Socket\n[q0]Socket Bonus: +9 Stamina\n\nDurability 40 / 40\nRequires Level 80\nSell Price: 5 30 27"},
    [43592] = {name = "[q4]Polar Boots", additional_info = "Binds when equipped\nFeet Leather\n398 Armor\n+129 Stamina\n+86 Frost Resistance\n\n[q0]Red Socket\n[q0]Yellow Socket\n[q0]Socket Bonus: +9 Stamina\n\nDurability 60 / 60\nRequires Level 80\nSell Price: 7 98 30"},
    [43593] = {name = "[q4]Icy Scale Chestguard", additional_info = "Binds when equipped\nChest Mail\n1286 Armor\n+169 Stamina\n+115 Frost Resistance\n\n[q0]Red Socket\n[q0]Yellow Socket\n[q0]Blue Socket\n[q0]Socket Bonus: +12 Stamina\n\nDurability 140 / 140\nRequires Level 80\nSell Price: 11 91 12"},
    [43594] = {name = "[q4]Icy Scale Belt", additional_info = "Binds when equipped\nWaist Mail\n723 Armor\n+129 Stamina\n+86 Frost Resistance\n\n[q0]Red Socket\n[q0]Yellow Socket\n[q0]Socket Bonus: +9 Stamina\n\nDurability 50 / 50\nRequires Level 80\nSell Price: 5 95 56"},
    [43595] = {name = "[q4]Icy Scale Boots", additional_info = "Binds when equipped\nFeet Mail\n884 Armor\n+129 Stamina\n+86 Frost Resistance\n\n[q0]Red Socket\n[q0]Yellow Socket\n[q0]Socket Bonus: +9 Stamina\n\nDurability 70 / 70\nRequires Level 80\nSell Price: 9 72 57"},
    [43596] = {name = "[q0]Monster - Staff, Blood Elf A02 Blue - High Blue Flames", additional_info = "Two-Hand Staff\n1 - 2 Damage Speed 2.00\n(0.75 damage per second)\nDurability 20 / 20\nSell Price: 2"},
    [43597] = {name = "[q4]Design: Titanium Frostguard Ring", additional_info = "Binds when picked up\nRequires Jewelcrafting (420)\n[q2]Use: Teaches you how to craft a Titanium Frostguard Ring\n\n[q4]Titanium Frostguard Ring\nBinds when equipped\nUnique-Equipped\nFinger\n+100 Stamina\n+68 Frost Resistance\n\n[q0]Red Socket\n[q0]Socket Bonus: +6 Stamina\n\nRequires Level 80\nSell Price: 7 56 23\nRequires Titanium Bar (2), Eternal Water (3), Eternal Fire (3), Frozen Orb"},
    [43598] = {name = "[q0]Monster - Dagger, Northrend D02 Red (Red Flame)", additional_info = "One-Hand Dagger\n1 - 2 Damage Speed 1.60\n(0.94 damage per second)\nDurability 16 / 16\nSell Price: 2"},
    [43599] = {name = "[q3]Big Blizzard Bear", additional_info = "Binds to account\nMount\nRequires Level 20\nRequires Riding (75)\n[q2]Use: Teaches you how to summon this mount.\nSummons and dismisses your Big Blizzard Bear. This mount changes depending on your Riding skill."},
    [43600] = {name = "Brunnhildar Harpoon", additional_info = "Two-Hand Polearm\n176 - 265 Damage Speed 3.80\n(58.03 damage per second)\nDurability 85 / 85\nRequires Level 75\n[q0]Increases attack power by 44 in Cat, Bear, Dire Bear, and Moonkin forms only.\n[q2]Equip: Inflicts 4 to 6 additional Frost damage per swing.\nSell Price: 4 12"},
    [43601] = {name = "Brunnhildar Great Axe", additional_info = "Two-Hand Axe\n186 - 279 Damage Speed 4.00\n(58.13 damage per second)\nDurability 85 / 85\nRequires Level 75\n[q2]Equip: Inflicts 4 to 6 additional Frost damage per swing.\nSell Price: 4 12"},
    [43608] = {name = "Copperclaw's Volatile Oil", additional_info = "Quest Item\nUnique\n[q2]Use: Assembles Armored Soldier Dummy in the Broken Front. (20 Sec Cooldown)"},
    [43609] = {name = "Pile of Bones", additional_info = "Quest Item\n[q]\"A fallen soldier, stripped of flesh.\""},
    [43610] = {name = "Abandoned Helm", additional_info = "Quest Item\n[q]\"A battleworn Alliance helm.\""},
    [43611] = {name = "[q4]Krol Cleaver", additional_info = "Binds when equipped\nOne-Hand Sword\n261 - 485 Damage Speed 2.60\n(143.46 damage per second)\n+36 Agility\n+42 Stamina\nDurability 105 / 105\nRequires Level 80\n[q2]Equip: Increases attack power by 70.\n[q2]Equip: Increases your armor penetration by 28.\nSell Price: 19 98 12"},
    [43612] = {name = "[q4]Spineslicer", additional_info = "Binds when equipped\nThrown Thrown\n328 - 493 Damage Speed 2.20\n(186.59 damage per second)\n+26 Agility\n+22 Stamina\nRequires Level 80\n[q2]Equip: Improves hit rating by 25.\n[q2]Equip: Increases attack power by 48.\nSell Price: 7 12 45"},
    [43613] = {name = "[q4]The Dusk Blade", additional_info = "Binds when equipped\nOne-Hand Dagger\n206 - 310 Damage Speed 1.80\n(143.33 damage per second)\nDurability 75 / 75\nRequires Level 80\n[q0]Increases attack power by 1239 in Cat, Bear, Dire Bear, and Moonkin forms only.\n[q2]Chance on hit: You gain an additional 155 armor penetration rating for 10 sec. This effect stacks up to 3 times.\nSell Price: 20 12 44"},
    [43614] = {name = "Broken Wrath Elixir", additional_info = "[q2]Use: Combine 5 Broken Wrath Elixir into a Wrath Elixir.\nSell Price: 8 75"},
    [43615] = {name = "Saurfang's Battle Armor", additional_info = "Quest Item\nUnique"},
    [43616] = {name = "Abandoned Armor", additional_info = "Quest Item\n[q]\"A pierced Alliance breastplate.\""},
    [43617] = {name = "Monster - Staff, Dalaran Blue", additional_info = "Binds when picked up\nUnique\nTwo-Hand Staff\n3 Damage Speed 3.00\n(1.00 damage per second)\n+20 Shadow Resistance\nDurability 20 / 20Classes: Priest"},
    [43618] = {name = "Monster - Staff, Dalaran Green", additional_info = "Binds when picked up\nUnique\nTwo-Hand Staff\n3 Damage Speed 3.00\n(1.00 damage per second)\n+20 Shadow Resistance\nDurability 20 / 20Classes: Priest"},
    [43619] = {name = "Monster - Staff, Dalaran Red", additional_info = "Binds when picked up\nUnique\nTwo-Hand Staff\n3 Damage Speed 3.00\n(1.00 damage per second)\n+20 Shadow Resistance\nDurability 20 / 20Classes: Priest"},
    [43620] = {name = "Broken Spellpower Elixir", additional_info = "[q2]Use: Combine 5 Broken Spellpower Elixir into a Spellpower Elixir.\nSell Price: 8 75"},
    [43621] = {name = "Broken Noggenfogger Elixir", additional_info = "[q2]Use: Combine 5 Broken Noggenfogger Elixir into a Noggenfogger Elixir.\nSell Price: 8 75"},
    [43622] = {name = "[q2]Froststeel Lockbox", additional_info = "[q0]Locked\n Requires Lockpicking (375)\nSell Price: 7 50"},
    [43623] = {name = "[q0]Monster - Axe, 2H Northrend C01 Brown (Executioner)", additional_info = "Two-Hand Axe\n2 - 4 Damage Speed 3.70\n(0.81 damage per second)\nDurability 20 / 20\nSell Price: 2"},
    [43624] = {name = "[q3]Titanium Lockbox", additional_info = "[q0]Locked\n Requires Lockpicking (400)\nSell Price: 7 50"},
    [43625] = {name = "[q0]Monster - Axe, 1H Northrend C01 Stone (Executioner)", additional_info = "One-Hand Axe\n1 - 4 Damage Speed 3.70\n(0.68 damage per second)\nDurability 20 / 20\nSell Price: 2"},
    [43626] = {name = "[q2]Happy Pet Snack", additional_info = "Binds when picked up\n[q2]Use: Feed your Non-Combat Pet a snack.\nSell Price: 2 50"},
    [43627] = {name = "Thrall's Gold Coin", additional_info = "Binds when picked up\n[q2]Use: Throw this coin back into the Dalaran fountain.\n[q]\"Grom, may you rest well, old friend.\"\nSell Price: 1 25"},
    [43628] = {name = "Lady Jaina Proudmoore's Gold Coin", additional_info = "Binds when picked up\n[q2]Use: Throw this coin back into the Dalaran fountain.\n[q]\"Arthas, my love, please come back to me.\"\nSell Price: 1 25"},
    [43629] = {name = "Uther Lightbringer's Gold Coin", additional_info = "Binds when picked up\n[q2]Use: Throw this coin back into the Dalaran fountain.\n[q]\"Young Arthas must learn patience to temper his power. I will pray that he one day learns how to lead with care rather than force.\"\nSell Price: 1 25"},
    [43630] = {name = "Tirion Fordring's Gold Coin", additional_info = "Binds when picked up\n[q2]Use: Throw this coin back into the Dalaran fountain.\n[q]\"It is my wish that my dear Taelan will grow strong enough to defend the people he cares for.\"\nSell Price: 1 25"},
    [43631] = {name = "Teron's Gold Coin", additional_info = "Binds when picked up\n[q2]Use: Throw this coin back into the Dalaran fountain.\n[q]\"Wishes are a fool's pastime. Take this coin as payment for your precious Eye.\"\nSell Price: 1 25"},
    [43632] = {name = "Sylvanas Windrunner's Gold Coin", additional_info = "Binds when picked up\n[q2]Use: Throw this coin back into the Dalaran fountain.\n[q]\"I hope my sisters and I can grow up and get married together. This coin appears to be very old.\"\nSell Price: 1 25"},
    [43633] = {name = "Prince Kael'thas Sunstrider's Gold Coin", additional_info = "Binds when picked up\n[q2]Use: Throw this coin back into the Dalaran fountain.\n[q]\"That young apprentice Jaina is quite attractive for a human. I hope she recognizes my elegance and power.\"\nSell Price: 1 25"},
    [43634] = {name = "Lady Katrana Prestor's Gold Coin", additional_info = "Binds when picked up\n[q2]Use: Throw this coin back into the Dalaran fountain.\n[q]\"Listen, little wishing fountain. You'll give me all your power if you know what's good for you.\"\nSell Price: 1 25"},
    [43635] = {name = "Kel'Thuzad's Gold Coin", additional_info = "Binds when picked up\n[q2]Use: Throw this coin back into the Dalaran fountain.\n[q]\"Sometimes... I wish someone would come along and just give me a big, long hug.\"\nSell Price: 1 25"},
    [43636] = {name = "Chromie's Gold Coin", additional_info = "Binds when picked up\n[q2]Use: Throw this coin back into the Dalaran fountain.\n[q]\"Just once, I wish someone would greet me without making a stupid joke about gnomes or time travel.\"\nSell Price: 1 25"},
    [43637] = {name = "Brann Bronzebeard's Gold Coin", additional_info = "Binds when picked up\n[q2]Use: Throw this coin back into the Dalaran fountain.\n[q]\"Brann Bronzebeard was here.\"\nSell Price: 1 25"},
    [43638] = {name = "Arugal's Gold Coin", additional_info = "Binds when picked up\n[q2]Use: Throw this coin back into the Dalaran fountain.\n[q]\"I wish someday to retire to my own tidy little estate, with a bunch of pet dogs to keep me company.\"\nSell Price: 1 25"},
    [43639] = {name = "Arthas' Gold Coin", additional_info = "Binds when picked up\n[q2]Use: Throw this coin back into the Dalaran fountain.\n[q]\"Already, I've a kingdom in my prospects, a land to rule. What to ask for? Perhaps a frozen scone...\"\nSell Price: 1 25"},
    [43640] = {name = "Archimonde's Gold Coin", additional_info = "Binds when picked up\n[q2]Use: Throw this coin back into the Dalaran fountain.\n[q]\"I wish to know how you survived my wrath, little fountain.\"\nSell Price: 1 25"},
    [43641] = {name = "Anduin Wrynn's Gold Coin", additional_info = "Binds when picked up\n[q2]Use: Throw this coin back into the Dalaran fountain.\n[q]\"I wish I would grow up, it feels like I've been 10 for years.\"\nSell Price: 1 25"},
    [43643] = {name = "[q0]Prince Magni Bronzebeard's Silver Coin", additional_info = "[q]\"I hope that my father and brothers outlive me. I'll not make much of a king.\"\nSell Price: 62"},
    [43644] = {name = "[q0]A Peasant's Silver Coin", additional_info = "[q]\"I'm so forgetful! I wish I had a better memory. Wait, didn't I already throw a coin into here?\"\nSell Price: 62"},
    [43645] = {name = "[q0]Bent Fishing Hook", additional_info = "[q]\"Looks like someone tried to fish in this fountain. Who would do such a thing?\"\nSell Price: 62"},
    [43646] = {name = "Fountain Goldfish", additional_info = "Requires Level 65\n[q2]Use: Restores 7500 health over 30 sec. Must remain seated while eating.\nSell Price: 62"},
    [43647] = {name = "Shimmering Minnow", additional_info = "Requires Level 70\n[q2]Use: Restores 18480 health over 30 sec. Must remain seated while eating.\nSell Price: 62"},
    [43650] = {name = "Rusty Prison Key", additional_info = "Binds when picked up\n[q]\"Resembles a key used to open underwater treasure chests...\"\nSell Price: 62"},
    [43651] = {name = "[q5]Crafty's Pole", additional_info = "Binds when picked up\nUnique\nTwo-Hand Fishing Pole447 - 672 Damage Speed 3.00\n(186.50 damage per second)\nDurability 95 / 95\nRequires Fishing (1)\n[q0]Increases attack power by 1843 in Cat, Bear, Dire Bear, and Moonkin forms only.\nEquip: Fishing skill increased by 1000.\n[q]\"Just holding this fishing pole makes you shiver with excitement. This is possibly the most amazing thing you've ever seen.\"\nSell Price: 37 45 38"},
    [43652] = {name = "Slippery Eel", additional_info = "Requires Level 70\n[q2]Use: Restores 18480 health over 30 sec. If you spend at least 10 seconds eating you will become well fed and gain 40 dodge rating for 1 hour.\nSell Price: 62"},
    [43653] = {name = "[q0]Partially Eaten Fish", additional_info = "[q]\"Small tooth marks can be seen on the carcass.\"\nSell Price: 62"},
    [43654] = {name = "[q3]Tome of the Dawn", additional_info = "Binds when equipped\nHeld In Off-hand\n+6 Intellect\nRequires Level 20\n[q2]Equip: Increases spell power by 6.\nSell Price: 14"},
    [43655] = {name = "[q3]Book of Survival", additional_info = "Binds when equipped\nHeld In Off-hand\n+7 Stamina\nRequires Level 20\n[q2]Equip: Restores 7 health per 5 sec.\nSell Price: 14"},
    [43656] = {name = "[q3]Tome of Kings", additional_info = "Binds when equipped\nHeld In Off-hand\n+6 Stamina\nRequires Level 30\n[q2]Equip: Improves critical strike rating by 6.\n[q2]Equip: Improves hit rating by 5.\n[q2]Use: Increases your stats by 10 for 1 min. (10 Min Cooldown)\nSell Price: 14"},
    [43657] = {name = "[q3]Royal Guide of Escape Routes", additional_info = "Binds when equipped\nHeld In Off-hand\nRequires Level 30\n[q2]Equip: Improves haste rating by 11.\n[q2]Use: Heal you for 270 to 330. (5 Min Cooldown)\nSell Price: 14"},
    [43658] = {name = "[q0]Partially Rusted File", additional_info = "[q]\"The file has a slight green tinge to it.\"\nSell Price: 62"},
    [43659] = {name = "[q0]Bloodied Prison Shank", additional_info = "One-Hand Dagger\n93 - 174 Damage Speed 2.00\n(66.75 damage per second)\nDurability 55 / 55\nRequires Level 70\n[q0]Increases attack power by 168 in Cat, Bear, Dire Bear, and Moonkin forms only.\n[q]\"The business end of this shank looks like profits were high this year.\"\nSell Price: 3 33 19"},
    [43660] = {name = "[q3]Fire Eater's Guide", additional_info = "Binds when equipped\nHeld In Off-hand\nRequires Level 40\n[q2]Equip: Improves critical strike rating by 9.\n[q2]Equip: Increases spell power by 12.\n[q2]Use: Breathe fire on enemies in front of you, dealing 278 to 322 Fire damage. (2 Min Cooldown)\nSell Price: 14"},
    [43661] = {name = "[q3]Book of Stars", additional_info = "Binds when equipped\nHeld In Off-hand\nRequires Level 40\n[q2]Equip: Improves hit rating by 14.\n[q2]Use: Restores 315 to 385 mana. (2 Min Cooldown)\nSell Price: 14"},
    [43662] = {name = "Axe of the Plunderer", additional_info = "Quest Item\nUnique\n[q]\"You would expect this axe to be exceptionally sharp. It's not. The vrykul must have been relying upon his immense strength to hew through his foes.\""},
    [43663] = {name = "[q3]Stormbound Tome", additional_info = "Binds when equipped\nHeld In Off-hand\n+10 Intellect\nRequires Level 50\n[q2]Equip: Improves critical strike rating by 9.\n[q2]Equip: Increases spell power by 12.\n[q2]Use: Shocks an enemy for 12 to 800 Nature damage. (2 Min Cooldown)\nSell Price: 14"},
    [43664] = {name = "[q3]Manual of Clouds", additional_info = "Binds when equipped\nHeld In Off-hand\n+9 Intellect\n+9 Spirit\nRequires Level 50\n[q2]Equip: Increases spell power by 12.\n[q2]Use: Increases your Spirit by 50 for 1 min. (5 Min Cooldown)\nSell Price: 14"},
    [43665] = {name = "Keristrasza's Broken Heart", additional_info = "Quest Item\nUnique\n[q]\"A tragic end to a sad tale. If only Malygos's abuse of Keristrasza hadn't driven her insane.\""},
    [43666] = {name = "[q3]Hellfire Tome", additional_info = "Binds when equipped\nHeld In Off-hand\n+20 Fire Resistance\nRequires Level 60\n[q2]Equip: Increases spell power by 25.\nSell Price: 14"},
    [43667] = {name = "[q3]Book of Clever Tricks", additional_info = "Binds when equipped\nHeld In Off-hand\n+27 Stamina\nRequires Level 60\n[q2]Equip: Improves critical strike rating by 7.\n[q2]Equip: Improves hit rating by 11.\n[q2]Use: Increases your dodge rating by 200 for 15 sec. (5 Min Cooldown)\nSell Price: 14"},
    [43668] = {name = "Ley Line Tuner", additional_info = "Quest Item\nUnique\n[q]\"You're not quite sure what to make of it. It definitely seethes with arcane magic, but how can something so small be so important?\""},
    [43669] = {name = "Locket of the Deceased Queen", additional_info = "Quest Item\nUnique\n[q]\"The only reminder that King Ymiron had of his love, Queen Angerboda.\""},
    [43670] = {name = "Prophet's Enchanted Tiki", additional_info = "Quest Item\nUnique\n[q]\"It seems to have lost all of its mojo with the demise of its bearer.\""},
    [43671] = {name = "Glyph of Corpse Explosion", additional_info = "[q9]Minor Glyph\nClasses: Death Knight\nRequires Level 55\n[q2]Use: Permanently teaches you this glyph.\n\nIncreases the radius of effect on Corpse Explosion by 5 yards.\nSell Price: 1"},
    [43672] = {name = "Glyph of Pestilence", additional_info = "[q9]Minor Glyph\nClasses: Death Knight\nRequires Level 55\n[q2]Use: Permanently teaches you this glyph.\n\nIncreases the radius of your Pestilence effect by 5 yards.\nSell Price: 1"},
    [43673] = {name = "Glyph of Raise Dead", additional_info = "[q9]Minor Glyph\nClasses: Death Knight\nRequires Level 55\n[q2]Use: Permanently teaches you this glyph.\n\nYour Raise Dead spell no longer requires a reagent.\nSell Price: 1"},
    [43674] = {name = "Glyph of Dash", additional_info = "[q9]Minor Glyph\nClasses: Druid\nRequires Level 16\n[q2]Use: Permanently teaches you this glyph.\n\nReduces the cooldown of your Dash ability by 20%.\nSell Price: 1"},
    [43675] = {name = "[q0]Fandral Staghelm's Silver Coin", additional_info = "[q]\"The War of the Shifting Sands... I wish I could forget it ever happened.\"\nSell Price: 62"},
    [43676] = {name = "[q0]Arcanist Doan's Silver Coin", additional_info = "[q]\"Oh, why won't you notice me? Abbendis, I would follow you anywhere. I wish you would notice me...\"\nSell Price: 62"},
    [43677] = {name = "[q0]High Tinker Mekkatorque's Silver Coin", additional_info = "[q]\"How does this fountain even work? I wonder if I could make one.\"\nSell Price: 62"},
    [43678] = {name = "[q0]Antonidas' Silver Coin", additional_info = "[q]\"Grant me the strength to accept the things that I cannot change, the courage to change the things I can and the wisdom to know the difference.\"\nSell Price: 62"},
    [43679] = {name = "[q0]Muradin Bronzebeard's Silver Coin", additional_info = "[q]\"May the Holy Light protect us on our expedition to the frozen north.\"\nSell Price: 62"},
    [43680] = {name = "[q0]King Varian Wrynn's Silver Coin", additional_info = "[q]\"I wish the uprising back at home would settle itself soon. I wouldn't want anyone to be hurt.\"\nSell Price: 62"},
    [43681] = {name = "[q0]King Terenas Menethil's Silver Coin", additional_info = "[q]\"May my son Arthas always act in the best interest of his people.\"\nSell Price: 62"},
    [43682] = {name = "[q0]King Anasterian Sunstrider's Silver Coin", additional_info = "[q]\"I hope young Kael'thas realizes that one day he must lead our people.\"\nSell Price: 62"},
    [43683] = {name = "[q0]Khadgar's Silver Coin", additional_info = "[q]\"Turalyon and Alleria, wherever you are, may you be well.\"\nSell Price: 62"},
    [43684] = {name = "[q0]Medivh's Silver Coin", additional_info = "[q]\" \"\nSell Price: 62"},
    [43685] = {name = "[q0]Maiev Shadowsong's Silver Coin", additional_info = "[q]\"Where's Illidan?\"\nSell Price: 62"},
    [43686] = {name = "[q0]Alleria's Silver Coin", additional_info = "[q]\"May my sisters realize their full potential, the name Windrunner known as result of their deeds.\"\nSell Price: 62"},
    [43687] = {name = "[q0]Aegwynn's Silver Coin", additional_info = "[q]\"I really wish you mages would get your heads out from inside your own... books.\"\nSell Price: 62"},
    [43688] = {name = "Weeping Quarry Document", additional_info = "Quest Item"},
    [43689] = {name = "Weeping Quarry Ledger", additional_info = "Quest Item"},
    [43690] = {name = "Weeping Quarry Schedule", additional_info = "Quest Item"},
    [43691] = {name = "Weeping Quarry Map", additional_info = "Quest Item"},
    [43692] = {name = "[q0]Monster - Sword, 2H Deathknight B01 Red (Red Glow)", additional_info = "Two-Hand Sword\n1 - 2 Damage Speed 2.00\n(0.75 damage per second)\nDurability 20 / 20\nSell Price: 2"},
    [43693] = {name = "Mojo Remnant of Akali", additional_info = "Quest Item\nUnique\n[q]\"Hard to believe that this is all that is left of the once mighty rhino god.\""},
    [43694] = {name = "[q0]Drowned Rat", additional_info = "[q]\"Looks like falling in the soup pot did not work out so well this time.\"\nSell Price: 62"},
    [43695] = {name = "Half Full Bottle of Prison Moonshine", additional_info = "[q2]Use: A strong alcoholic beverage.\n[q]\"Also useful for removing paint.\"\nSell Price: 12"},
    [43696] = {name = "Half Empty Bottle of Prison Moonshine", additional_info = "[q2]Use: A strong alcoholic beverage.\n[q]\"Also useful for removing paint.\"\nSell Price: 12"},
    [43697] = {name = "Artifact from the Nathrezim Homeworld", additional_info = "Quest Item\nUnique\n[q]\"What strange construction. It must be one of the most alien-looking objects you've ever seen.\""},
    [43698] = {name = "[q3]Giant Sewer Rat", additional_info = "Binds when picked up\n[q2]Use: Teaches you how to summon this companion.\n[q2]Right Click to summon and dismiss a Giant Sewer Rat\nSell Price: 10"},
    [43699] = {name = "The Curse of Flesh Disc", additional_info = "Quest Item\nUnique\n[q]\"There's information on this thing? What? There's no writing!\""},
    [43701] = {name = "[q0]A Footman's Copper Coin", additional_info = "[q]\"Wish I had that cousin of mine's duty to do nothing more than lug wood around carelessly...\"\nSell Price: 62"},
    [43702] = {name = "[q0]Alonsus Faol's Copper Coin", additional_info = "[q]\"One day, I hope to spread the path of the Light to the common people and teach them the value of the Three Virtues.\"\nSell Price: 62"},
    [43703] = {name = "[q0]Ansirem's Copper Coin", additional_info = "[q]\"I wish for happiness and acceptance for my daughter. She feels so out of place here...\"\nSell Price: 62"},
    [43704] = {name = "[q0]Attumen's Copper Coin", additional_info = "[q]\"Can I have a more comfortable saddle? My hindquarters ache.\"\nSell Price: 62"},
    [43705] = {name = "[q0]Danath's Copper Coin", additional_info = "[q]\"I hope a troll dies, right... NOW.\"\nSell Price: 62"},
    [43706] = {name = "[q0]Dornaa's Shiny Copper Coin", additional_info = "[q]\"I wish that that jerk Arthas would fall into a pile of magnataur doody!\"\nSell Price: 62"},
    [43707] = {name = "[q0]Eitrigg's Copper Coin", additional_info = "[q]\"May Tirion's quest here in Northrend end with success, or may he die honorably in battle.\"\nSell Price: 62"},
    [43708] = {name = "[q0]Elling Trias' Copper Coin", additional_info = "[q]\"Being a rogue is hard work. Someday I hope to pursue my life's one true passion...\"\nSell Price: 62"},
    [43709] = {name = "[q0]Falstad Wildhammer's Copper Coin", additional_info = "[q]\"I hope I end up in another book eventually.\"\nSell Price: 62"},
    [43710] = {name = "[q0]Genn's Copper Coin", additional_info = "[q]\"Pah, the fountains in Gilneas could grant ten times as many wishes as Dalaran's!\"\nSell Price: 62"},
    [43711] = {name = "[q0]Inigo's Copper Coin", additional_info = "[q]\"I wish I had my father back...\"\nSell Price: 62"},
    [43712] = {name = "[q0]Krasus' Copper Coin", additional_info = "[q]\"My prayers go out to my brothers and sisters who still suffer in the heart of Grim Batol. I WILL free them.\"\nSell Price: 62"},
    [43713] = {name = "[q0]Kryll's Copper Coin", additional_info = "[q]\"Boom. Now boom? I wish for a boom. Boom go! This coin must be broken, I wonder if it'll explode.\"\nSell Price: 62"},
    [43714] = {name = "[q0]Landro Longshot's Copper Coin", additional_info = "[q]\"I wish I'd kept that coin...\"\nSell Price: 62"},
    [43715] = {name = "[q0]Molok's Copper Coin", additional_info = "[q]\"Just once -- that's all I ask for, just once -- let the lass ride with me...\"\nSell Price: 62"},
    [43716] = {name = "[q0]Murky's Copper Coin", additional_info = "[q]\"I wish the water in Northrend wasn't so cold, it makes me sleepy.\"\nSell Price: 62"},
    [43717] = {name = "[q0]Princess Calia Menethil's Copper Coin", additional_info = "[q]\"I hope that handsome nobleman Lord Prestor notices me! He's so dreamy!\"\nSell Price: 62"},
    [43718] = {name = "[q0]Private Marcus Jonathan's Copper Coin", additional_info = "[q]\"I wish to grow a glorious, bushy mustache someday.\"\nSell Price: 62"},
    [43719] = {name = "[q0]Salandria's Shiny Copper Coin", additional_info = "[q]\"Someday, I'm gonna be more powerful than all of these mages!\"\nSell Price: 62"},
    [43720] = {name = "[q0]Squire Rowe's Copper Coin", additional_info = "[q]\"I hope I can get transferred out of Stormwind eventually and see Cersei again. Nothing good ever happens in this city.\"\nSell Price: 62"},
    [43721] = {name = "[q0]Stalvan's Copper Coin", additional_info = "[q]\"You mages refuse to provide me that which hastens the inevitable fate of two people in love, when only one is too naive to see it. I wish you all ruin.\"\nSell Price: 62"},
    [43722] = {name = "[q0]Vereesa's Copper Coin", additional_info = "[q]\"Asto're da shan're. Turus Fulo Il'amare, A'Talah Adore. Isera'duna...\"\nSell Price: 62"},
    [43723] = {name = "[q0]Vargoth's Copper Coin", additional_info = "[q]\"I wish Captain Sanders would hurry up with my shipment of wine.\"\nSell Price: 62"},
    [43724] = {name = "Celestial Ruby Ring", additional_info = "Quest Item\nUnique\n[q]\"Ring? It's more like a necklace and a heavy one at that!\""},
    [43725] = {name = "Glyph of Ghost Wolf", additional_info = "[q9]Minor Glyph\nClasses: Shaman\nRequires Level 16\n[q2]Use: Permanently teaches you this glyph.\n\nYour Ghost Wolf form regenerates an additional 1% of your maximum health every 5 sec.\nSell Price: 1"},
    [43726] = {name = "The Idle Crown of Anub'arak", additional_info = "Quest Item\nUnique\n[q]\"The crypt lord still carried it though he lost his royal title long ago when he entered the service of the Lich King.\""},
