    [44554] = {name = "[q3]Flying Carpet", additional_info = "Mount\nRequires Level 60\nRequires Tailoring (300)\nRequires Expert Riding\n[q2]Use: Teaches you how to summon this rug. Can only be used in Outland or Northrend.\n[q2]Summons and dismisses a Flying Carpet. Can only be used in Outland and Northrend. Requires 300 skill in tailoring to ride."},
