    [44918] = {name = "[q2]Schematic: Cluster Launcher", additional_info = "Binds when picked up\nRequires Engineering (275)\n[q2]Use: Teaches you how to make a Firework Cluster Launcher.\nSell Price: 40\nCluster Launcher\n[q2]Use: Place on the ground to launch cluster rockets. Lasts 30 minutes.\nRequires Mithril Casing , Goblin Rocket Fuel"},
