    [44920] = {name = "Glyph of Blast Wave", additional_info = "[q9]Minor Glyph\nClasses: Mage\nRequires Level 70\n[q2]Use: Permanently teaches you this glyph.\n\nThe mana cost of your Blast Wave spell is reduced by 15%, but it no longer knocks enemies back.\nSell Price: 1"},
