    [44932] = {name = "[q4]Pattern: Windripper Boots", additional_info = "Binds when picked up\nRequires Leatherworking (440)\n[q2]Use: Teaches you how to make Windripper Boots.\n\n[q4]Windripper Boots\nBinds when equipped\nFeet Leather\n388 Armor\n+57 Stamina\n+48 Intellect\nDurability 60 / 60\nRequires Level 80\n[q2]Equip: Improves critical strike rating by 66.\n[q2]Equip: Increases spell power by 77.\nSell Price: 7 57 60\nRequires Heavy Borean Leather (10), Eternal Air (5), Eternal Water (5), Frozen Orb"},
    [44933] = {name = "[q4]Pattern: Windripper Leggings", additional_info = "Binds when picked up\nRequires Leatherworking (440)\n[q2]Use: Teaches you how to make Windripper Leggings.\n\n[q4]Windripper Leggings\nBinds when equipped\nLegs Leather\n494 Armor\n+78 Stamina\n+64 Intellect\nDurability 90 / 90\nRequires Level 80\n[q2]Equip: Improves critical strike rating by 89.\n[q2]Equip: Increases spell power by 105.\nSell Price: 10 13 67\nRequires Heavy Borean Leather (12), Eternal Air (6), Eternal Water (6), Frozen Orb"},
    [44934] = {name = "[q4]Loop of the Kirin Tor", additional_info = "Binds when picked up\nUnique\nFinger\n+49 Stamina\n+34 Intellect\n+36 Spirit\nRequires Level 80\n[q2]Equip: Restores 14 mana per 5 sec.\n[q2]Equip: Increases spell power by 59.\n[q2]Use: Teleports the caster to Dalaran. (30 Min Cooldown)\nSell Price: 21 25"},
    [44935] = {name = "[q4]Ring of the Kirin Tor", additional_info = "Binds when picked up\nUnique\nFinger\n+50 Strength\n+75 Stamina\nRequires Level 80\n[q2]Equip: Improves critical strike rating by 34.\n[q2]Equip: Increases your expertise rating by 31.\n[q2]Use: Teleports the caster to Dalaran. (30 Min Cooldown)\nSell Price: 21 25"},
    [44936] = {name = "[q3]Titanium Plating", additional_info = "Requires Level 70\n[q2]Use: Permanently attach lightweight titanium plating to a shield, increasing block value by 81 and reducing the duration of Disarm effects by 50%. Does not stack with other similar effects.\n\n Attaching Titanium Plating to your shield causes it to become soulbound.\nSell Price: 3"},
    [44937] = {name = "[q3]Plans: Titanium Plating", additional_info = "Binds when picked up\nRequires Blacksmithing (450)\nRequiresAlliance Vanguard\n- Exalted\n[q2]Use: Teaches you how to make a Titanium Plating.\n\n[q3]Titanium Plating\nRequires Level 70\n[q2]Use: Permanently attach lightweight titanium plating to a shield, increasing block value by 81 and reducing the duration of Disarm effects by 50%. Does not stack with other similar effects.\n\n Attaching Titanium Plating to your shield causes it to become soulbound.\nSell Price: 3\nRequires Titanium Bar (4), Eternal Shadow (4)"},
    [44938] = {name = "[q3]Plans: Titanium Plating", additional_info = "Binds when picked up\nRequires Blacksmithing (450)\nRequiresHorde Expedition\n- Exalted\n[q2]Use: Teaches you how to make a Titanium Plating.\n\n[q3]Titanium Plating\nRequires Level 70\n[q2]Use: Permanently attach lightweight titanium plating to a shield, increasing block value by 81 and reducing the duration of Disarm effects by 50%. Does not stack with other similar effects.\n\n Attaching Titanium Plating to your shield causes it to become soulbound.\nSell Price: 3\nRequires Titanium Bar (4), Eternal Shadow (4)"},
    [44939] = {name = "Lesser Flask of Resistance", additional_info = "Requires Level 70\n[q2]Use: Increases your resistance to all schools of magic by 50 for 1 hour. Counts as both a Battle and Guardian elixir. This effect persists through death. (3 Sec Cooldown)\nSell Price: 8 75"},
    [44940] = {name = "Corn-Breaded Sausage", additional_info = "Requires Level 75\n[q2]Use: Restores 22500 health over 30 sec. Must remain seated while eating.\n[q]\"...on a stick!\"\nSell Price: 8"},
    [44941] = {name = "Fresh-Squeezed Limeade", additional_info = "Requires Level 70\n[q2]Use: Restores 12840 mana over 30 sec. Must remain seated while drinking.\nSell Price: 4 25"},
    [44943] = {name = "[q3]Icy Prism", additional_info = "Unique\n[q]\"Several dazzling gems hide inside....\"\n[q2]<Right Click to Open>"},
    [44944] = {name = "[q3]Formula: Enchant Bracer - Major Stamina", additional_info = "Binds when picked up\nRequires Enchanting (450)\n[q2]Use: Teaches you how to permanently enchant bracers to increase Stamina by 40. Requires a level 60 or higher item.\n[q2]Permanently enchant bracers to increase Stamina by 40. Requires a level 60 or higher item."},
    [44945] = {name = "[q3]Formula: Enchant Weapon - Titanguard", additional_info = "Binds when picked up\nRequires Enchanting (450)\n[q2]Use: Teaches you how to permanently enchant a melee weapon to increase Stamina by 50. Requires a level 60 or higher item.\n[q2]Permanently enchant a melee weapon to increase Stamina by 50. Requires a level 60 or higher item."},
    [44946] = {name = "[q3]Scroll of Enchant Weapon - Titanguard", additional_info = "[q2]Use: Permanently enchant a melee weapon to increase Stamina by 50. Requires a level 60 or higher item."},
    [44947] = {name = "Scroll of Enchant Bracer - Major Stamina", additional_info = "[q2]Use: Permanently enchant bracers to increase Stamina by 40. Requires a level 60 or higher item."},
