    [44949] = {name = "[q4]Unbreakable Healing Amplifiers", additional_info = "Binds when picked up\nHead Plate\n1821 Armor\n+55 Stamina\n+60 Intellect\n\n[q0]Meta Socket\n[q0]Yellow Socket\n[q0]Socket Bonus: +9 Spell Power\n\nDurability 100 / 100\nRequires Level 72\nRequires Engineering (400)\n[q2]Equip: Improves critical strike rating by 73.\n[q2]Equip: Increases spell power by 87.\n[q2]Use: Allows you to look far into the distance. (3 Sec Cooldown)\nSell Price: 10 54 72"},
    [44950] = {name = "Raelorasz' Spark", additional_info = "Quest Item\nUnique\n[q2]Use: Lights a signal fire that will summon Keristrasza to your location. (2 Sec Cooldown)"},
    [44951] = {name = "Box of Bombs", additional_info = "[q]\"Contains Saronite Bombs. Lots of them.\"\n[q2]<Right Click to Open>"},
