    [44953] = {name = "Worg Tartare", additional_info = "Requires Level 70\n[q2]Use: Restores 22500 health and 19200 mana over 30 sec. If you spend at least 10 seconds eating you will become well fed and gain 40 Hit Rating and 40 Stamina for 1 hour.\nSell Price: 4"},
    [44954] = {name = "[q2]Recipe: Worg Tartare", additional_info = "Binds when picked up\nRequires Cooking (400)\n[q2]Use: Teaches you how to mince worg meat into Worg Tartare.\n[q2]This delicacy is best served raw and thus requires no cooking fire.\n\nWorg Tartare\nRequires Level 70\n[q2]Use: Restores 22500 health and 19200 mana over 30 sec. If you spend at least 10 seconds eating you will become well fed and gain 40 Hit Rating and 40 Stamina for 1 hour.\nSell Price: 4\nRequires Worg Haunch (2), Northern Spices"},
    [44955] = {name = "Glyph of Arcane Blast", additional_info = "[q9]Major Glyph\nClasses: Mage\nRequires Level 64\n[q2]Use: Permanently teaches you this glyph.\n\nIncreases the damage from your Arcane Blast buff by 3%.\nSell Price: 1"},
    [44956] = {name = "[q3]Goblin's Guide to Elementium", additional_info = "Binds when picked up\nRequires Mining (300)\n[q2]Use: Teaches you how to smelt Elementium.\nSell Price: 2\n[q5]Elementium Bar\nSell Price: 10\nRequires Elementium Ore , Arcanite Bar (10), Fiery Core , Elemental Flux (3)"},
    [44957] = {name = "[q4]Greater Inscription of the Gladiator", additional_info = "Binds when picked up\nRequires Level 70\nUse: Permanently adds 30 Stamina and 15 resilience rating to a shoulder slot item.\n\n Enchanting the item causes it to become soulbound."},
    [44958] = {name = "Ethereal Oil", additional_info = "[q2]Use: Make yourself translucent for 5 min.\nSell Price: 10"},
    [44963] = {name = "[q4]Earthen Leg Armor", additional_info = "Requires Level 80\nUse: Permanently attach earthen armor onto pants to increase resilience rating by 40 and Stamina by 28.\n\n Enchanting the item causes it to become soulbound.Sell Price: 2"},
