    [45076] = {name = "[q4]Teldrassil Protector", additional_info = "Binds when picked up\nOne-Hand Axe\n170 - 317 Damage Speed 1.70\n(143.24 damage per second)\n+29 Strength\n+43 Stamina\nDurability 105 / 105\nRequires Level 80\n[q2]Equip: Increases defense rating by 44.\n[q2]Equip: Increases your parry rating by 19."},
    [45077] = {name = "[q4]Dagger of the Rising Moon", additional_info = "Binds when picked up\nUnique-Equipped\nOne-Hand Dagger\n195 - 293 Damage Speed 1.70\n(143.53 damage per second)\n+43 Stamina\nDurability 75 / 75\nRequires Level 80\n[q0]Increases attack power by 1241 in Cat, Bear, Dire Bear, and Moonkin forms only.\n[q2]Equip: Improves critical strike rating by 22.\n[q2]Equip: Improves hit rating by 38.\n[q2]Equip: Increases attack power by 78."},
    [45078] = {name = "[q4]Dagger of Lunar Purity", additional_info = "Binds when picked up\nMain Hand Dagger\n59 - 189 Damage Speed 1.50\n(82.67 damage per second)\n+28 Stamina\n+38 Intellect\n+38 Spirit\nDurability 75 / 75\nRequires Level 80\n[q0]Increases attack power by 389 in Cat, Bear, Dire Bear, and Moonkin forms only.\n[q2]Equip: Improves haste rating by 30.\n[q2]Equip: Increases spell power by 408."},
