    [46097] = {name = "[q4]Caress of Insanity", additional_info = "Binds when picked up\nOne-Hand Mace\n371 - 690 Damage Speed 2.70\n(196.48 damage per second)\n+45 Agility\n+48 Stamina\n\n[q0]Red Socket\n[q0]Socket Bonus: +8 Attack Power\n\nDurability 105 / 105\nRequires Level 80\n[q0]Increases attack power by 1983 in Cat, Bear, Dire Bear, and Moonkin forms only.\n[q2]Equip: Improves haste rating by 28.\n[q2]Equip: Increases attack power by 118.\n[q2]Equip: Increases your expertise rating by 39.\nSell Price: 23 60 19"},
    [46098] = {name = "[q3]Scroll of Enchant Weapon - Blood Draining", additional_info = "[q2]Use: Permanently enchants your weapon to sometimes grant Blood Reserve when striking an enemy or inflicting damage with bleed attacks. When you fall below 35% health, Blood Reserve restores 360 to 440 health. Lasts 20 sec and stacks up to 5 times.\n\n This enchantment requires the wielder is at least level 75."},
    [46099] = {name = "[q3]Horn of the Black Wolf", additional_info = "Binds when picked up\nMountRequires any Horde race\nRequires Level 20\nRequires Riding (75)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses a rideable Black Wolf.\nSell Price: 25"},
    [46100] = {name = "[q3]White Kodo", additional_info = "Binds when picked up\nMountRequires any Horde race\nRequires Level 20\nRequires Riding (75)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses a rideable White Kodo.\nSell Price: 25"},
    [46101] = {name = "[q4]Blue Skeletal Warhorse", additional_info = "Binds when picked up\nMountRequires any Horde race\nRequires Level 40\nRequires Riding (150)\n[q2]Use: Teaches you how to summon this mount. This is a very fast mount.\n[q2]Summons and dismisses a rideable Blue Skeletal Warhorse. This is a very fast mount.\nSell Price: 2 50"},
