    [46803] = {name = "Recipe: Spice Bread Stuffing", additional_info = "Binds when picked up\nRequires Cooking (1)\n[q2]Use: Teaches you how to cook Spice Bread Stuffing.\n\nSpice Bread Stuffing\nDuration: 7 days (real time)\n[q2]Use: Restores 4% of your health and mana every sec for 30 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed and gain [floor(cond($GT($pl, 15), $pl - 15, 0) * 0.554) + 4] hit rating and Stamina for 1 hour.\nSell Price: 1\nRequires Spice Bread , Autumnal Herbs"},
    [46804] = {name = "Recipe: Pumpkin Pie", additional_info = "Binds when picked up\nRequires Cooking (100)\n[q2]Use: Teaches you how to bake Pumpkin Pie.\n\nPumpkin Pie\nDuration: 7 days (real time)\n[q2]Use: Restores 4% of your health and mana every sec for 30 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed and gain [floor(cond($GT($pl, 15), $pl - 15, 0) * 0.554) + 4] Spirit and Stamina for 1 hour.\nSell Price: 1\nRequires Ripe Tirisfal Pumpkin , Honey"},
    [46805] = {name = "Recipe: Cranberry Chutney", additional_info = "Binds when picked up\nRequires Cooking (160)\n[q2]Use: Teaches you how to cook Cranberry Chutney.\n\nCranberry Chutney\nDuration: 7 days (real time)\n[q2]Use: Restores 4% of your health and mana every sec for 30 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed and gain [floor(cond($GT($pl, 15), $pl - 15, 0) * 0.6616) + 4] spell power and [floor(cond($GT($pl, 15), $pl - 15, 0) * 0.554) + 4] Stamina for 1 hour.\nSell Price: 1\nRequires Tangy Southfury Cranberries , Honey"},
    [46806] = {name = "Recipe: Candied Sweet Potato", additional_info = "Binds when picked up\nRequires Cooking (220)\n[q2]Use: Teaches you how to cook Candied Sweet Potato.\n\nCandied Sweet Potato\nDuration: 7 days (real time)\n[q2]Use: Restores 4% of your health and mana every sec for 30 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed and gain [floor(cond($GT($pl, 15), $pl - 15, 0) * 0.554) + 4] haste rating and Stamina for 1 hour.\nSell Price: 1\nRequires Mulgore Sweet Potato , Honey , Autumnal Herbs"},
    [46807] = {name = "Recipe: Slow-Roasted Turkey", additional_info = "Binds when picked up\nRequires Cooking (280)\n[q2]Use: Teaches you how to cook Slow-Roasted Turkey.\n\nSlow-Roasted Turkey\nDuration: 7 days (real time)\n[q2]Use: Restores 4% of your health and mana every sec for 30 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed and gain [floor(cond($GT($pl, 15), $pl - 15, 0) * 1.108) + 8] attack power and [floor(cond($GT($pl, 15), $pl - 15, 0) * 0.554) + 4] Stamina for 1 hour.\nSell Price: 1\nRequires Wild Turkey , Honey (2), Autumnal Herbs"},
