    [46839] = {name = "[q4]Frostwolf Insignia Rank 7", additional_info = "Binds when picked up\nUnique\nTrinket\nRequires Level 80\n[q2]Equip: Improves your resilience rating by 84.\n[q2]Equip: Increases your expertise rating by 84.\n[q2]Use: Returns you to the sanctuary of Frostwolf Keep.\n[q]\"The Eye of Command\""},
    [46840] = {name = "[q4]Frostwolf Insignia Rank 7", additional_info = "Binds when picked up\nUnique\nTrinket\nRequires Level 80\n[q2]Equip: Improves your resilience rating by 84.\n[q2]Equip: Each time you deal damage, you have a chance to do an additional 390 to 450 Frost damage. (Proc chance: 50%, 13s cooldown)\n[q2]Use: Returns you to the sanctuary of Frostwolf Keep.\n[q]\"The Eye of Command\""},
    [46841] = {name = "[q0]Monster - Spear, Rusty (1H)", additional_info = "Two-Hand Dagger\n1 - 2 Damage Speed 2.00\n(0.75 damage per second)\nDurability 16 / 16\nSell Price: 2"},
    [46842] = {name = "[q4]Crusader's Band", additional_info = "Binds when picked up\nUnique\nFinger\n+100 Stamina\nRequires Level 80\n[q2]Use: Teleports the caster to the Argent Tournament Grounds. (30 Min Cooldown)\nSell Price: 21 25"},
    [46843] = {name = "Argent Crusader's Banner", additional_info = "Binds when picked up\nToy\n[q2]Use: Right Click to plant your Argent Crusader's Banner. (3 Min Cooldown)"},
    [46845] = {name = "Massive Seaforium Charge 2", additional_info = "Unique\n[q2]Use: Places a massive seaforium charge which will detonate after 10 seconds.\n[q2]Seaforium charges will be dropped on death."},
    [46847] = {name = "Seaforium Bombs", additional_info = "Isle of Conquest\nUnique\nRequires Level 70\n[q2]Use: Places a seaforium bomb which will detonate after 10 seconds.\n[q2]Seaforium bombs will be removed on death."},
    [46849] = {name = "[q2]Titanium Powder", additional_info = "[q]\"Timothy Jones of Dalaran would be very interested in this fine powder.\"\nSell Price: 5"},
    [46852] = {name = "[q3]H17 Ammunition Buddy", additional_info = "Requires Level 80\n[q2]Use: Creates 1000 customized arrows or bullets for your equipped ranged weapon.\n30 Charges\n[q]\"In order to protect trademark Goblin Ingenuity, tampering with this Ammunition Buddy will make it explode. Thank you.\""},
    [46854] = {name = "[q4]Saronite Decimators", additional_info = "Binds when picked up\nAmmo Arrow\nAdds 93 damage per second"},
    [46859] = {name = "Stolen Tallstrider Leg", additional_info = "Quest Item"},
    [46860] = {name = "Whimsical Skull Mask", additional_info = "Binds when picked up\nHead\nRequiresDay of the Dead\nSell Price: 1"},
    [46861] = {name = "Bouquet of Orange Marigolds", additional_info = "Binds when picked up\nHeld In Off-hand\n[q2]Use: Detect lesser invisibility for 30 sec. Only works during the Day of the Dead. (30 Sec Cooldown)\n[q]\"Said to attract spirits and help one communicate with the departed on the Day of the Dead.\"\nSell Price: 25"},
    [46870] = {name = "Confessor's Prayer Book", additional_info = "Quest Item\n[q2]Use: Administer last rites to a Slain Tualiq Villager (10 yard range)."},
