    [46887] = {name = "Bountiful Feast", additional_info = "Duration: 7 days (real time)\nRequires Cooking (350)\n[q2]Use: Set out a bountiful feast to feed a very hungry party. Restores 4% health and mana every sec for 30 sec. If you spend at least 10 sec eating you will become well fed and gain [floor(cond($GT($pl, 15), $pl - 15, 0) * 1.108) + 8] attack power, [floor(cond($GT($pl, 15), $pl - 15, 0) * 0.6616) + 4] spell power, and [floor(cond($GT($pl, 15), $pl - 15, 0) * 0.554) + 4] Stamina for 1 hour.\nSell Price: 6 25"},
    [46888] = {name = "Bountiful Basket", additional_info = "Duration: 7 days (real time)\nRequires Cooking (350)\n[q2]Use: Combine Spice Bread Stuffing, Candied Sweet Potato, Cranberry Chutney, Pumpkin Pie and a Slow-Roasted Turkey to create a Bountiful Feast. Delicious!\nSell Price: 5"},
    [46889] = {name = "Jormungar Egg Sac", additional_info = "Quest Item"},
    [46892] = {name = "[q3]Murkimus' Tiny Spear", additional_info = "Binds when picked up\nUnique\n[q2]Use: Teaches you how to summon this companion.\n[q2]Right Click to summon and dismiss Murkimus the Gladiator."},
    [46893] = {name = "Earthshaker Drum", additional_info = "Quest Item\n[q2]Use: Pound your drum near a Mysterious Snow Mound in the Foot Steppes."},
    [46894] = {name = "[q3]Enchanted Jade", additional_info = "Binds to account\n[q2]Use: Teaches you how to summon this companion.\n[q2]Right Click to summon and dismiss your jade tiger."},
    [46895] = {name = "Black Cage Key", additional_info = "Quest Item\n[q2]Use: Opens a Cage at Deathspeaker's Watch."},
