    [186683] = {name = "Formula: Enchant Ring - Stats", additional_info = "Binds when picked up\nRequires Enchanting (375)\nRequiresThe Scale of the Sands\n- Revered\n[q2]Use: Teaches you how to permanently enchant a ring to increase all stats by 4.\n[q2]Permanently enchant a ring to increase all stats by 4. Only the enchanter's rings can be enchanted, and enchanting a ring will cause it to become soulbound. Requires a level 35 or higher item.\nSell Price: 5"},
    [187048] = {name = "[q3]Pattern: Greater Drums of Restoration", additional_info = "Binds when picked up\nRequires Leatherworking (350)\nRequiresKurenai\n- Honored\n[q2]Use: Teaches you how to craft Greater Drums of Restoration.\nSell Price: 4\n[q3]Greater Drums of Restoration\nRequires Leatherworking (350)\n[q2]Use: Restores 600 health and mana to party members within 40 yards over 15 sec. Drums can be used while shapeshifted. Cannot affect targets level 80 or higher. (2 Min Cooldown)\n50 ChargesSell Price: 50\nRequires Heavy Knothide Leather (6), Nether Dragonscales (4)"},
    [187049] = {name = "[q3]Pattern: Greater Drums of Speed", additional_info = "Binds when picked up\nRequires Leatherworking (345)\nRequiresKurenai\n- Honored\n[q2]Use: Teaches you how to craft Greater Drums of Speed.\nSell Price: 4\n[q3]Greater Drums of Speed\nRequires Leatherworking (340)\n[q2]Use: Increases movement speed of party members within 40 yards by 15%. Lasts 30 sec. Drums can be used while shapeshifted. (2 Min Cooldown)\n50 ChargesSell Price: 50\nRequires Heavy Knothide Leather (6), Wind Scales (4)"},
